export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Basket ----------
  const basketPos = new THREE.Vector3(0.14, 0, 0.02);
  const basketTopR = 0.11, basketBotR = 0.085, basketH = 0.08;

  const wickerMat = new THREE.MeshStandardMaterial({
    color: 0xa8743a, roughness: 0.9, side: THREE.DoubleSide,
  });
  const rimMat = new THREE.MeshStandardMaterial({
    color: 0x8a5a2b, roughness: 0.8, emissive: 0x000000,
  });

  const basket = new THREE.Group();
  basket.name = 'Basket';
  basket.position.copy(basketPos);
  root.add(basket);

  const wall = new THREE.Mesh(
    new THREE.CylinderGeometry(basketTopR, basketBotR, basketH, 32, 1, true), wickerMat);
  wall.position.y = basketH / 2;
  basket.add(wall);

  const bottom = new THREE.Mesh(new THREE.CircleGeometry(basketBotR, 32), wickerMat);
  bottom.rotation.x = -Math.PI / 2;
  bottom.position.y = 0.002;
  basket.add(bottom);

  const rim = new THREE.Mesh(new THREE.TorusGeometry(basketTopR, 0.007, 8, 40), rimMat);
  rim.rotation.x = Math.PI / 2;
  rim.position.y = basketH;
  basket.add(rim);

  // horizontal weave bands
  const bandGeo = new THREE.TorusGeometry(1, 0.003, 6, 40);
  for (let i = 1; i <= 2; i++) {
    const t = i / 3;
    const band = new THREE.Mesh(bandGeo, rimMat);
    const r = basketBotR + (basketTopR - basketBotR) * t + 0.001;
    band.scale.set(r, r, 1);
    band.rotation.x = Math.PI / 2;
    band.position.y = basketH * t;
    basket.add(band);
  }

  const handle = new THREE.Mesh(new THREE.TorusGeometry(basketTopR, 0.006, 8, 32, Math.PI), rimMat);
  handle.position.y = basketH;
  basket.add(handle);

  // ---------- Fruits ----------
  const fruits = [];

  function makeFruit(name, price, mesh, restY, startPos, slot) {
    mesh.name = name;
    mesh.position.set(startPos[0], restY, startPos[2]);
    root.add(mesh);
    traits(mesh, { grab: true });
    fruits.push({
      name, price, mesh, restY,
      start: new THREE.Vector3(startPos[0], restY, startPos[2]),
      slot: new THREE.Vector3(basketPos.x + slot[0], 0.004 + restY, basketPos.z + slot[2]),
      target: null, wasGrabbed: false, inBasket: false,
    });
  }

  // Apple
  const apple = new THREE.Mesh(
    new THREE.SphereGeometry(0.035, 28, 14),
    new THREE.MeshStandardMaterial({ color: 0xc8202a, roughness: 0.45 }));
  apple.scale.set(1, 0.92, 1);
  const stem = new THREE.Mesh(
    new THREE.CylinderGeometry(0.003, 0.003, 0.02, 6),
    new THREE.MeshStandardMaterial({ color: 0x5a3b1c }));
  stem.position.y = 0.038;
  stem.rotation.z = 0.25;
  apple.add(stem);
  const leaf = new THREE.Mesh(
    new THREE.SphereGeometry(0.009, 8, 6),
    new THREE.MeshStandardMaterial({ color: 0x3c9a3a }));
  leaf.scale.set(1.6, 0.3, 0.8);
  leaf.position.set(0.01, 0.042, 0);
  apple.add(leaf);
  makeFruit('Apple', 0.75, apple, 0.032, [-0.32, 0, 0.04], [-0.045, 0, 0.02]);

  // Banana: a bent torus arc lying flat
  const banGeo = new THREE.TorusGeometry(0.06, 0.015, 10, 20, 1.9);
  banGeo.center();
  const banana = new THREE.Mesh(banGeo,
    new THREE.MeshStandardMaterial({ color: 0xf2d33a, roughness: 0.6 }));
  banana.rotation.x = -Math.PI / 2;
  const tip = new THREE.Mesh(
    new THREE.SphereGeometry(0.006, 8, 6),
    new THREE.MeshStandardMaterial({ color: 0x4a3a1a }));
  const a = 1.9;
  tip.position.set(0, 0, 0); // placed after geometry recentering below
  banGeo.computeBoundingBox();
  // put a dark tip near one end of the arc
  const bb = banGeo.boundingBox;
  tip.position.set(bb.max.x - 0.004, bb.min.y + 0.01, 0);
  banana.add(tip);
  makeFruit('Banana', 0.30, banana, 0.016, [-0.19, 0, 0.05], [0.035, 0, 0.035]);

  // Orange
  const orange = new THREE.Mesh(
    new THREE.SphereGeometry(0.036, 28, 14),
    new THREE.MeshStandardMaterial({ color: 0xff8c1a, roughness: 0.75 }));
  const navel = new THREE.Mesh(
    new THREE.SphereGeometry(0.005, 8, 6),
    new THREE.MeshStandardMaterial({ color: 0x6a8a2a }));
  navel.position.y = 0.035;
  orange.add(navel);
  makeFruit('Orange', 0.95, orange, 0.036, [-0.06, 0, 0.06], [0.0, 0, -0.045]);

  // ---------- Panel ----------
  const panel = ui(`
    <style>
      .card { flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 24px; padding-right: 24px; border-radius: 18px; background-color: #1f2228;
              width: 460px; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .hint { color: #aeb5c0; font-size: 20px; }
      .row { flex-direction: row; justify-content: space-between; align-items: center; }
      .item { color: #d7dbe2; font-size: 22px; }
      .price { color: #d7dbe2; font-size: 22px; }
      .totalRow { flex-direction: row; justify-content: space-between; align-items: center;
                  padding-top: 10px; border-color: #3a3f48; border-width: 0px; }
      .totalLabel { color: #ffffff; font-size: 28px; font-weight: 700; }
      .total { color: #7ee08a; font-size: 30px; font-weight: 700; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #3a4250; align-items: center; justify-content: center; }
      .btnText { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Fruit Basket</span>
      <span class="hint" id="hint">Pinch a fruit and drop it into the basket.</span>
      <div class="row"><span class="item" id="appleRow">Apple  $0.75</span><span class="price" id="appleSt">-</span></div>
      <div class="row"><span class="item" id="bananaRow">Banana  $0.30</span><span class="price" id="bananaSt">-</span></div>
      <div class="row"><span class="item" id="orangeRow">Orange  $0.95</span><span class="price" id="orangeSt">-</span></div>
      <div class="totalRow"><span class="totalLabel">Total</span><span class="total" id="total">$0.00</span></div>
      <button class="btn" id="reset"><span class="btnText">Empty basket</span></button>
    </div>`, { width: 0.32, position: [-0.05, 0.3, -0.14], rotationY: 0 });
  root.add(panel.object3D);

  const statusIds = { Apple: 'appleSt', Banana: 'bananaSt', Orange: 'orangeSt' };

  panel.on('reset', 'click', () => {
    for (const f of fruits) {
      if (isGrabbed(f.mesh)) continue;
      f.target = f.start.clone();
      f.inBasket = false;
    }
    panel.set('hint', { text: 'Basket emptied. Try again!' });
  });

  // ---------- Logic ----------
  function overBasket(p) {
    const dx = p.x - basketPos.x, dz = p.z - basketPos.z;
    return dx * dx + dz * dz < (basketTopR - 0.01) * (basketTopR - 0.01) && p.y < basketH + 0.12;
  }

  let lastKey = '';
  const SPEED = 0.12; // m/s settling speed
  const tmp = new THREE.Vector3();

  return {
    root,
    update(time, delta) {
      let hovering = false;
      for (const f of fruits) {
        const m = f.mesh;
        if (isGrabbed(m)) {
          f.wasGrabbed = true;
          f.target = null;
          f.inBasket = overBasket(m.position);
          if (f.inBasket) hovering = true;
          continue;
        }
        if (f.wasGrabbed) {
          // just released: decide where it settles
          f.wasGrabbed = false;
          f.inBasket = overBasket(m.position);
          if (f.inBasket) {
            f.target = f.slot.clone();
            panel.set('hint', { text: f.name + ' added to the basket.' });
          } else {
            f.target = new THREE.Vector3(m.position.x, f.restY, m.position.z);
            panel.set('hint', { text: f.name + ' is outside the basket.' });
          }
        }
        if (f.target) {
          tmp.subVectors(f.target, m.position);
          const d = tmp.length();
          const step = SPEED * delta;
          if (d <= step) { m.position.copy(f.target); f.target = null; }
          else m.position.addScaledVector(tmp, step / d);
        }
      }

      rimMat.emissive.setHex(hovering ? 0x2a6a2a : 0x000000);

      // update panel only when contents change
      let key = '';
      let total = 0;
      for (const f of fruits) {
        key += f.inBasket ? '1' : '0';
        if (f.inBasket) total += f.price;
      }
      if (key !== lastKey) {
        lastKey = key;
        for (const f of fruits) {
          panel.set(statusIds[f.name], f.inBasket
            ? { text: 'in basket', color: '#7ee08a' }
            : { text: '-', color: '#7a818c' });
        }
        panel.set('total', { text: '$' + total.toFixed(2) });
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();
  const TOTAL = 5;

  // ---------- Quiz data ----------
  function randInt(a, b) { return a + Math.floor(Math.random() * (b - a + 1)); }
  function shuffle(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      const t = arr[i]; arr[i] = arr[j]; arr[j] = t;
    }
    return arr;
  }
  function makeQuestion(used) {
    let a, b, key;
    do {
      a = randInt(2, 9); b = randInt(2, 9);
      key = Math.min(a, b) + 'x' + Math.max(a, b);
    } while (used.has(key));
    used.add(key);
    const correct = a * b;
    const pool = [a * (b + 1), a * (b - 1), (a + 1) * b, (a - 1) * b, correct + 10, correct - 10, correct + 1, correct - 1, correct + 2];
    const distractors = [];
    for (const p of shuffle(pool)) {
      if (p > 0 && p !== correct && !distractors.includes(p)) distractors.push(p);
      if (distractors.length === 3) break;
    }
    const options = shuffle([correct, ...distractors]);
    return { a, b, correct, options };
  }
  let questions = [];
  function newQuiz() {
    const used = new Set();
    questions = [];
    for (let i = 0; i < TOTAL; i++) questions.push(makeQuestion(used));
  }

  // ---------- Main quiz panel ----------
  const panel = ui(`
    <style>
      .card { flex-direction: column; gap: 14px; padding-top: 22px; padding-bottom: 22px;
              padding-left: 24px; padding-right: 24px; border-radius: 22px; background-color: #1f2228;
              width: 480px; align-items: center; }
      .top { flex-direction: row; justify-content: space-between; width: 432px; }
      .small { color: #aeb6c2; font-size: 20px; }
      .scoreText { color: #ffd54a; font-size: 22px; font-weight: 700; }
      .q { color: #ffffff; font-size: 54px; font-weight: 700; }
      .row { flex-direction: row; gap: 14px; }
      .ans { width: 208px; height: 72px; border-radius: 16px; background-color: #34404f;
             align-items: center; justify-content: center; }
      .ansText { color: #ffffff; font-size: 32px; font-weight: 700; }
      .fb { color: #d7dbe2; font-size: 22px; text-align: center; }
      .next { padding-top: 12px; padding-bottom: 12px; padding-left: 24px; padding-right: 24px;
              border-radius: 14px; background-color: #2f6fdb; }
      .btnText { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <div class="top">
        <span class="small" id="progress">Question 1 of 5</span>
        <span class="scoreText" id="score">Score: 0 / 5</span>
      </div>
      <span class="q" id="question">? × ? = ?</span>
      <div class="row">
        <button class="ans" id="a0"><span class="ansText" id="a0t">0</span></button>
        <button class="ans" id="a1"><span class="ansText" id="a1t">0</span></button>
      </div>
      <div class="row">
        <button class="ans" id="a2"><span class="ansText" id="a2t">0</span></button>
        <button class="ans" id="a3"><span class="ansText" id="a3t">0</span></button>
      </div>
      <span class="fb" id="feedback">Press the correct answer.</span>
      <button class="next" id="next"><span class="btnText" id="nextText">Next question</span></button>
    </div>`, { width: 0.36, position: [0, 0.23, -0.04] });
  root.add(panel.object3D);

  // ---------- Array model (grabbable hint board) ----------
  const board = new THREE.Group();
  board.name = 'ArrayBoard';
  board.position.set(-0.3, 0.17, 0.02);
  board.rotation.y = 0.4;
  root.add(board);

  const plate = new THREE.Mesh(
    new THREE.BoxGeometry(0.21, 0.21, 0.012),
    new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.8 }),
  );
  board.add(plate);

  const MAX = 81;
  const cubes = new THREE.InstancedMesh(
    new THREE.BoxGeometry(0.014, 0.014, 0.014),
    new THREE.MeshStandardMaterial({ color: 0x4fc3f7, emissive: 0x0d4a66, emissiveIntensity: 0.6, roughness: 0.4 }),
    MAX,
  );
  cubes.name = 'ArrayCubes';
  board.add(cubes);
  const tmp = new THREE.Object3D();
  function showArray(rows, cols) {
    const s = 0.02;
    let k = 0;
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        tmp.position.set((c - (cols - 1) / 2) * s, ((rows - 1) / 2 - r) * s, 0.013);
        tmp.updateMatrix();
        cubes.setMatrixAt(k++, tmp.matrix);
      }
    }
    cubes.count = k;
    cubes.instanceMatrix.needsUpdate = true;
  }

  const caption = ui(`
    <style>
      .c { flex-direction: column; padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
           border-radius: 14px; background-color: #1a1d22; width: 420px; align-items: center; gap: 4px; }
      .t { color: #4fc3f7; font-size: 26px; font-weight: 700; }
      .s { color: #aeb6c2; font-size: 20px; }
    </style>
    <div class="c">
      <span class="t" id="cap">7 rows of 8</span>
      <span class="s">Hint: count the array. Pinch to move it.</span>
    </div>`, { width: 0.21, position: [0, -0.14, 0.01] });
  board.add(caption.object3D);

  traits(board, { grab: true });

  // ---------- Score stars ----------
  const starGeo = new THREE.OctahedronGeometry(0.02, 0);
  const stars = [];
  for (let i = 0; i < TOTAL; i++) {
    const m = new THREE.Mesh(starGeo, new THREE.MeshStandardMaterial({ color: 0x555b66, roughness: 0.5 }));
    m.name = 'ScoreStar' + (i + 1);
    m.position.set(0.28, 0.33 - i * 0.06, 0.02);
    root.add(m);
    stars.push(m);
  }
  function setStar(i, state) {
    const mat = stars[i].material;
    if (state === 'right') { mat.color.setHex(0xffd54a); mat.emissive.setHex(0xff9800); mat.emissiveIntensity = 0.8; }
    else if (state === 'wrong') { mat.color.setHex(0x8a2d2d); mat.emissive.setHex(0x000000); mat.emissiveIntensity = 0; }
    else { mat.color.setHex(0x555b66); mat.emissive.setHex(0x000000); mat.emissiveIntensity = 0; }
  }

  // ---------- Quiz flow ----------
  let index = 0, score = 0, answered = false, finished = false;
  const IDLE = '#34404f';

  function loadQuestion() {
    const q = questions[index];
    answered = false;
    panel.set('progress', { text: `Question ${index + 1} of ${TOTAL}` });
    panel.set('question', { text: `${q.a} × ${q.b} = ?` });
    for (let i = 0; i < 4; i++) {
      panel.set('a' + i + 't', { text: String(q.options[i]) });
      panel.set('a' + i, { backgroundColor: IDLE });
    }
    panel.set('feedback', { text: 'Press the correct answer.', color: '#d7dbe2' });
    panel.set('next', { display: 'none' });
    showArray(q.a, q.b);
    caption.set('cap', { text: `${q.a} rows of ${q.b}` });
  }

  function startQuiz() {
    newQuiz();
    index = 0; score = 0; finished = false;
    panel.set('score', { text: `Score: 0 / ${TOTAL}` });
    for (let i = 0; i < TOTAL; i++) setStar(i, 'pending');
    loadQuestion();
  }

  function choose(i) {
    if (answered || finished) return;
    answered = true;
    const q = questions[index];
    const picked = q.options[i];
    const correctIdx = q.options.indexOf(q.correct);
    panel.set('a' + correctIdx, { backgroundColor: '#2e9e5b' });
    if (picked === q.correct) {
      score++;
      setStar(index, 'right');
      panel.set('feedback', { text: `Correct! ${q.a} × ${q.b} = ${q.correct}`, color: '#7ee2a0' });
    } else {
      panel.set('a' + i, { backgroundColor: '#c0392b' });
      setStar(index, 'wrong');
      panel.set('feedback', { text: `Not quite: ${q.a} × ${q.b} = ${q.correct}`, color: '#ff8a80' });
    }
    panel.set('score', { text: `Score: ${score} / ${TOTAL}` });
    panel.set('nextText', { text: index === TOTAL - 1 ? 'See results' : 'Next question' });
    panel.set('next', { display: 'flex' });
  }

  for (let i = 0; i < 4; i++) panel.on('a' + i, 'click', () => choose(i));

  panel.on('next', 'click', () => {
    if (finished) { startQuiz(); return; }
    if (!answered) return;
    index++;
    if (index >= TOTAL) {
      finished = true;
      panel.set('progress', { text: 'Quiz complete' });
      panel.set('question', { text: `${score} / ${TOTAL}` });
      const msg = score === TOTAL ? 'Perfect score! Amazing work.'
        : score >= 3 ? 'Great job! Keep practicing.' : 'Good try! Play again to improve.';
      panel.set('feedback', { text: msg, color: '#ffd54a' });
      panel.set('nextText', { text: 'Play again' });
      panel.set('next', { display: 'flex' });
      return;
    }
    loadQuestion();
  });

  startQuiz();

  return {
    root,
    update(time) {
      for (let i = 0; i < TOTAL; i++) {
        const s = stars[i];
        s.rotation.y = time * 0.8 + i;
        const pulse = (!finished && i === index && !answered) ? 1 + 0.15 * Math.sin(time * 4) : 1;
        s.scale.setScalar(pulse);
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---- Geometry setup ----
  const C = new THREE.Vector3(0, 0.2, 0); // Earth center
  const R = 0.15;                         // Earth radius in meters (6,371 km)
  const S = R / 6371;                     // meters per km

  // Layers from inside out. Radii in km. The crust is exaggerated so it is visible.
  const layers = [
    { name: 'Inner Core', inner: 0, outer: 1220 * S, color: 0xfff1a8, depth: '5,150–6,371 km deep', elev: -0.75,
      facts: 'A solid ball of iron and nickel about 1,220 km in radius. It is roughly 5,200 °C, about as hot as the Sun\'s surface, yet stays solid because of the enormous pressure.' },
    { name: 'Outer Core', inner: 1220 * S, outer: 3480 * S, color: 0xff9a2e, depth: '2,890–5,150 km deep', elev: -0.3,
      facts: 'Liquid iron and nickel, about 4,000–5,000 °C. Its swirling flow (the geodynamo) generates Earth\'s magnetic field.' },
    { name: 'Lower Mantle', inner: 3480 * S, outer: 5711 * S, color: 0xc4421f, depth: '660–2,890 km deep', elev: 0.15,
      facts: 'Hot, dense silicate rock under huge pressure. It is solid, but creeps very slowly over millions of years. The whole mantle makes up about 84% of Earth\'s volume.' },
    { name: 'Upper Mantle', inner: 5711 * S, outer: 0.141, color: 0xe8743a, depth: '~35–660 km deep', elev: 0.5,
      facts: 'Mostly peridotite rock rich in olivine. It includes the asthenosphere, a soft, slowly flowing zone that the tectonic plates glide on.' },
    { name: 'Crust', inner: 0.141, outer: R, color: 0x8a7a66, depth: '0–~35 km (5–70 km)', elev: 0.85,
      facts: 'The thin rocky outer shell: 5–10 km of basalt under oceans, 30–70 km of granite-like rock under continents. Less than 1% of Earth\'s volume. (Drawn thicker here so you can see it.)' },
  ];

  // Outer surface: sphere with a 90° wedge removed facing the user (+Z)
  const surface = new THREE.Mesh(
    new THREE.SphereGeometry(R, 48, 24, (3 * Math.PI) / 4, (3 * Math.PI) / 2),
    new THREE.MeshStandardMaterial({ color: 0x2a6fc9, roughness: 0.45, metalness: 0.05 }),
  );
  surface.name = 'Earth Surface';
  surface.position.copy(C);
  root.add(surface);

  // Cut faces: two vertical half-planes bounding the wedge
  const d1 = new THREE.Vector3(-Math.SQRT1_2, 0, Math.SQRT1_2);
  const faceAngles = [(-3 * Math.PI) / 4, -Math.PI / 4];
  const layerMeshes = [];
  layers.forEach((L, i) => {
    const geo = new THREE.RingGeometry(L.inner, L.outer, 48, 1, -Math.PI / 2, Math.PI);
    const mat = new THREE.MeshStandardMaterial({
      color: L.color, roughness: 0.8, side: THREE.DoubleSide,
      emissive: L.color, emissiveIntensity: i <= 1 ? 0.35 : 0.08,
    });
    L.mat = mat;
    L.baseEmissive = mat.emissiveIntensity;
    faceAngles.forEach((a) => {
      const m = new THREE.Mesh(geo, mat);
      m.name = L.name;
      m.position.copy(C);
      m.rotation.y = a;
      root.add(m);
      traits(m, { onPress: () => select(i) });
      layerMeshes.push(m);
    });
  });

  // ---- Labels with leader lines (left side) ----
  const labelX = -0.3, labelZ = 0.09;
  const lineMat = new THREE.LineBasicMaterial({ color: 0xe6e9ef });
  const labels = [];
  layers.forEach((L, i) => {
    const y = 0.09 + i * 0.06;
    const rm = (L.inner + L.outer) / 2;
    const anchor = C.clone()
      .addScaledVector(d1, rm * Math.cos(L.elev))
      .add(new THREE.Vector3(0, rm * Math.sin(L.elev), 0));
    const end = new THREE.Vector3(labelX + 0.075, y, labelZ - 0.02);
    const lg = new THREE.BufferGeometry().setFromPoints([anchor, end]);
    const line = new THREE.Line(lg, lineMat);
    root.add(line);

    // small dot at the anchor
    const dot = new THREE.Mesh(new THREE.SphereGeometry(0.003, 8, 6), new THREE.MeshBasicMaterial({ color: 0xffffff }));
    dot.position.copy(anchor);
    root.add(dot);

    const hex = '#' + L.color.toString(16).padStart(6, '0');
    const h = ui(`
      <style>
        .btn { flex-direction: column; gap: 2px; padding-top: 8px; padding-bottom: 8px;
               padding-left: 14px; padding-right: 14px; border-radius: 14px;
               background-color: #22262d; border-color: ${hex}; border-width: 3px; width: 300px; }
        .name { color: #ffffff; font-size: 26px; font-weight: 700; }
        .depth { color: #c9ced8; font-size: 18px; }
      </style>
      <button class="btn" id="btn">
        <span class="name">${L.name}</span>
        <span class="depth">${L.depth}</span>
      </button>`, { width: 0.15, position: [labelX, y, labelZ], rotationY: 0.35 });
    root.add(h.object3D);
    h.on('btn', 'click', () => select(i));
    labels.push(h);
  });

  // ---- Info panel (right side) ----
  const info = ui(`
    <style>
      .card { flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; width: 480px; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .sub { color: #ffb36b; font-size: 20px; }
      .body { color: #d7dbe2; font-size: 21px; }
      .note { color: #8f96a3; font-size: 17px; }
    </style>
    <div class="card">
      <span class="title" id="title">Layers of the Earth</span>
      <span class="sub" id="sub">Radius: 6,371 km</span>
      <span class="body" id="body">Earth is built in layers, densest at the center. Press a label or poke a layer in the cut-away to learn about it.</span>
      <span class="note">Layer sizes are to scale except the crust, which is drawn thicker.</span>
    </div>`, { width: 0.3, position: [0.31, 0.21, 0.06], rotationY: -0.4 });
  root.add(info.object3D);

  let selected = -1;
  function select(i) {
    if (selected >= 0) {
      layers[selected].mat.emissiveIntensity = layers[selected].baseEmissive;
      labels[selected].set('btn', { backgroundColor: '#22262d' });
    }
    selected = i;
    const L = layers[i];
    labels[i].set('btn', { backgroundColor: '#3a4150' });
    info.set('title', { text: L.name });
    info.set('sub', { text: L.depth });
    info.set('body', { text: L.facts });
  }

  return {
    root,
    update(time) {
      if (selected >= 0) {
        const L = layers[selected];
        L.mat.emissiveIntensity = 0.35 + 0.3 * (0.5 + 0.5 * Math.sin(time * 4));
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---- Helix parameters (B-DNA proportions: ~10 bp per turn, pitch about 1.7 x diameter) ----
  const BP = 20;
  const BP_PER_TURN = 10;
  const RISE = 0.016;              // meters per base pair
  const R = 0.045;                 // helix radius
  const GROOVE = (150 * Math.PI) / 180; // angular offset of strand 2 (creates major/minor grooves)
  const H = (BP - 1) * RISE;

  const helix = new THREE.Group();
  helix.name = 'DNA Double Helix';
  helix.position.set(-0.07, 0.07 + H / 2 + 0.02, 0);
  root.add(helix);

  // Right-handed helix with +Y up: x = r cos t, z = -r sin t
  function strandPoint(i, offset, target) {
    const t = (i / BP_PER_TURN) * Math.PI * 2 + offset;
    return target.set(R * Math.cos(t), i * RISE - H / 2, -R * Math.sin(t));
  }

  // ---- Sugar-phosphate backbones (tubes) ----
  const backboneMat1 = new THREE.MeshStandardMaterial({ color: 0xd9dee8, roughness: 0.45, metalness: 0.1 });
  const backboneMat2 = new THREE.MeshStandardMaterial({ color: 0x9aa7bd, roughness: 0.45, metalness: 0.1 });
  function makeStrand(offset, mat, name) {
    const pts = [];
    const steps = (BP - 1) * 4;
    for (let s = 0; s <= steps; s++) {
      pts.push(strandPoint(s / 4, offset, new THREE.Vector3()));
    }
    const curve = new THREE.CatmullRomCurve3(pts);
    const mesh = new THREE.Mesh(new THREE.TubeGeometry(curve, 160, 0.0055, 8, false), mat);
    mesh.name = name;
    helix.add(mesh);
  }
  makeStrand(0, backboneMat1, "Strand 5' to 3'");
  makeStrand(GROOVE, backboneMat2, "Strand 3' to 5'");

  // ---- Phosphate nodes (instanced spheres) ----
  const nodeGeo = new THREE.SphereGeometry(0.009, 16, 10);
  const nodeMat = new THREE.MeshStandardMaterial({ color: 0xffa94d, roughness: 0.4, emissive: 0x3a1a00, emissiveIntensity: 0.4 });
  const nodes = new THREE.InstancedMesh(nodeGeo, nodeMat, BP * 2);
  nodes.name = 'Phosphates';
  const m = new THREE.Matrix4();
  const v1 = new THREE.Vector3(), v2 = new THREE.Vector3(), mid = new THREE.Vector3();
  for (let i = 0; i < BP; i++) {
    m.makeTranslation(strandPoint(i, 0, v1));
    nodes.setMatrixAt(i * 2, m);
    m.makeTranslation(strandPoint(i, GROOVE, v1));
    nodes.setMatrixAt(i * 2 + 1, m);
  }
  helix.add(nodes);

  // ---- Base pairs: each rung = two half-cylinders, one per base ----
  const rungGeo = new THREE.CylinderGeometry(0.0045, 0.0045, 1, 10);
  const rungMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.5 });
  const rungs = new THREE.InstancedMesh(rungGeo, rungMat, BP * 2);
  rungs.name = 'Base pairs';
  const up = new THREE.Vector3(0, 1, 0);
  const dir = new THREE.Vector3(), pos = new THREE.Vector3(), scl = new THREE.Vector3();
  const q = new THREE.Quaternion();
  function placeHalf(index, from, to) {
    dir.subVectors(to, from);
    const len = dir.length();
    dir.normalize();
    q.setFromUnitVectors(up, dir);
    pos.addVectors(from, to).multiplyScalar(0.5);
    scl.set(1, len, 1);
    m.compose(pos, q, scl);
    rungs.setMatrixAt(index, m);
  }
  for (let i = 0; i < BP; i++) {
    strandPoint(i, 0, v1);
    strandPoint(i, GROOVE, v2);
    mid.addVectors(v1, v2).multiplyScalar(0.5);
    placeHalf(i * 2, v1, mid);
    placeHalf(i * 2 + 1, v2, mid);
  }
  helix.add(rungs);

  const BASE_COLORS = {
    A: new THREE.Color(0xe5484d),
    T: new THREE.Color(0x3e8ef7),
    G: new THREE.Color(0x30a46c),
    C: new THREE.Color(0xf5c518),
  };
  const PAIR = { A: 'T', T: 'A', G: 'C', C: 'G' };
  const seq = 'ATGCGTACCTAGGATCCGAT'.split('');

  function applySequence() {
    for (let i = 0; i < BP; i++) {
      rungs.setColorAt(i * 2, BASE_COLORS[seq[i]]);
      rungs.setColorAt(i * 2 + 1, BASE_COLORS[PAIR[seq[i]]]);
    }
    rungs.instanceColor.needsUpdate = true;
  }
  applySequence();

  // Small display stand (scenery, not interactive)
  const stand = new THREE.Mesh(
    new THREE.CylinderGeometry(0.06, 0.07, 0.012, 32),
    new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.7 }),
  );
  stand.name = 'Stand';
  stand.position.set(-0.07, 0.006, 0);
  root.add(stand);

  traits(helix, { grab: true });

  // ---- Info panel ----
  const panel = ui(`
    <style>
      .card { flex-direction: column; gap: 12px; padding-top: 20px; padding-bottom: 20px;
              padding-left: 24px; padding-right: 24px; border-radius: 18px; background-color: #1f2228; width: 520px; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .hint { color: #9fb3c8; font-size: 20px; }
      .body { color: #d7dbe2; font-size: 21px; }
      .seq { color: #ffffff; font-size: 20px; font-weight: 700; }
      .row { flex-direction: row; gap: 14px; align-items: center; }
      .chipA { padding-top: 4px; padding-bottom: 4px; padding-left: 10px; padding-right: 10px; border-radius: 8px; background-color: #e5484d; }
      .chipT { padding-top: 4px; padding-bottom: 4px; padding-left: 10px; padding-right: 10px; border-radius: 8px; background-color: #3e8ef7; }
      .chipG { padding-top: 4px; padding-bottom: 4px; padding-left: 10px; padding-right: 10px; border-radius: 8px; background-color: #30a46c; }
      .chipC { padding-top: 4px; padding-bottom: 4px; padding-left: 10px; padding-right: 10px; border-radius: 8px; background-color: #f5c518; }
      .chipText { color: #111111; font-size: 18px; font-weight: 700; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn2 { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px;
             border-radius: 12px; background-color: #3a3f48; }
      .btnText { color: #ffffff; font-size: 20px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">DNA Double Helix</span>
      <span class="hint">Pinch the helix to pick it up and turn it around.</span>
      <div class="row">
        <div class="chipA"><span class="chipText">A</span></div>
        <div class="chipT"><span class="chipText">T</span></div>
        <div class="chipG"><span class="chipText">G</span></div>
        <div class="chipC"><span class="chipText">C</span></div>
        <span class="body">Pairs: A-T, G-C</span>
      </div>
      <span class="seq" id="seq1">5'-</span>
      <span class="seq" id="seq2">3'-</span>
      <span class="body" id="fact">DNA is a right-handed double helix (B-form), about 2 nm wide.</span>
      <div class="row">
        <button class="btn" id="next"><span class="btnText">Next fact</span></button>
        <button class="btn2" id="shuffle"><span class="btnText">New sequence</span></button>
        <button class="btn2" id="spin"><span class="btnText" id="spinText">Spin: on</span></button>
      </div>
    </div>`, { width: 0.36, position: [0.22, 0.2, 0.02], rotationY: -0.4 });
  root.add(panel.object3D);

  function showSequence() {
    panel.set('seq1', { text: "5'-" + seq.join('') + "-3'" });
    panel.set('seq2', { text: "3'-" + seq.map((b) => PAIR[b]).join('') + "-5'" });
  }
  showSequence();

  const facts = [
    "DNA is a right-handed double helix (B-form), about 2 nm wide.",
    "One full turn spans about 10.5 base pairs and 3.4 nm.",
    "Adjacent base pairs are stacked about 0.34 nm apart.",
    "A pairs with T via 2 hydrogen bonds; G pairs with C via 3.",
    "The two strands are antiparallel: one runs 5' to 3', the other 3' to 5'.",
    "The backbone is alternating sugar (deoxyribose) and phosphate.",
    "The strands are offset, forming a wide major groove and a narrow minor groove. Turn it to find them!",
    "Watson and Crick published the double-helix model in 1953, using X-ray data from Rosalind Franklin.",
  ];
  let factIndex = 0;
  panel.on('next', 'click', () => {
    factIndex = (factIndex + 1) % facts.length;
    panel.set('fact', { text: facts[factIndex] });
  });

  const letters = ['A', 'T', 'G', 'C'];
  panel.on('shuffle', 'click', () => {
    for (let i = 0; i < BP; i++) seq[i] = letters[Math.floor(Math.random() * 4)];
    applySequence();
    showSequence();
    panel.set('fact', { text: "New sequence! Each base still pairs with its complement: A-T, G-C." });
  });

  let spinning = true;
  panel.on('spin', 'click', () => {
    spinning = !spinning;
    panel.set('spinText', { text: spinning ? 'Spin: on' : 'Spin: off' });
  });

  return {
    root,
    update(time, delta) {
      if (!spinning || isGrabbed(helix)) return;
      helix.rotation.y += delta * 0.35; // slow: outer edge moves < 0.02 m/s
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();
  root.name = 'MultiplicationQuiz';

  const TOTAL = 5;
  const COLORS = { idle: '#2f6fdb', correct: '#2e9e5b', wrong: '#c8443c', dim: '#3a3f48' };

  // ---------- Quiz panel ----------
  const panel = ui(`
    <style>
      .card { display: flex; flex-direction: column; gap: 12px; width: 560px;
              padding-top: 22px; padding-bottom: 22px; padding-left: 24px; padding-right: 24px;
              border-radius: 20px; background-color: #1f2228; border-width: 2px; border-color: #343a44; }
      .header { display: flex; flex-direction: row; justify-content: space-between; align-items: center; }
      .title { color: #ffffff; font-size: 28px; font-weight: 700; }
      .score { color: #ffd166; font-size: 26px; font-weight: 700; }
      .progress { color: #9aa3b2; font-size: 20px; }
      .question { color: #ffffff; font-size: 56px; font-weight: 700; text-align: center; }
      .row { display: flex; flex-direction: row; gap: 12px; }
      .ans { display: flex; width: 250px; height: 70px; align-items: center; justify-content: center;
             border-radius: 14px; background-color: #2f6fdb; }
      .ans-text { color: #ffffff; font-size: 32px; font-weight: 700; }
      .feedback { color: #d7dbe2; font-size: 22px; height: 56px; text-align: center; }
      .next { display: flex; height: 56px; align-items: center; justify-content: center;
              border-radius: 14px; background-color: #3a3f48; }
      .next-text { color: #ffffff; font-size: 24px; font-weight: 700; }
    </style>
    <div class="card">
      <div class="header">
        <span class="title">Multiplication Quiz</span>
        <span class="score" id="score">Score: 0 / 5</span>
      </div>
      <span class="progress" id="progress">Question 1 of 5</span>
      <span class="question" id="question">2 × 2 = ?</span>
      <div class="row" id="row0">
        <button class="ans" id="a0"><span class="ans-text" id="t0">0</span></button>
        <button class="ans" id="a1"><span class="ans-text" id="t1">0</span></button>
      </div>
      <div class="row" id="row1">
        <button class="ans" id="a2"><span class="ans-text" id="t2">0</span></button>
        <button class="ans" id="a3"><span class="ans-text" id="t3">0</span></button>
      </div>
      <span class="feedback" id="feedback">Pick the correct answer.</span>
      <button class="next" id="next"><span class="next-text" id="nextText">Next question</span></button>
    </div>`, { width: 0.38, position: [0.12, 0.27, 0], rotationY: -0.15 });
  root.add(panel.object3D);

  // ---------- Grabbable block array (visual model of a × b) ----------
  const blocks = new THREE.Group();
  blocks.name = 'BlockArrayBoard';
  blocks.position.set(-0.24, 0, 0.05);
  blocks.rotation.y = 0.3;

  const boardMat = new THREE.MeshStandardMaterial({ color: 0x23272e, roughness: 0.8 });
  const base = new THREE.Mesh(new THREE.BoxGeometry(0.24, 0.012, 0.06), boardMat);
  base.position.set(0, 0.006, 0);
  base.name = 'BoardBase';
  blocks.add(base);

  const board = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.22, 0.006), boardMat);
  board.position.set(0, 0.122, 0);
  board.name = 'BoardBack';
  blocks.add(board);

  const MAX_BLOCKS = 81;
  const PITCH = 0.022;
  const cubes = new THREE.InstancedMesh(
    new THREE.BoxGeometry(0.017, 0.017, 0.017),
    new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.45 }),
    MAX_BLOCKS,
  );
  cubes.name = 'BlockArray';
  blocks.add(cubes);
  root.add(blocks);
  traits(blocks, { grab: true });

  const dummy = new THREE.Object3D();
  const rowColorA = new THREE.Color(0x4fc3f7);
  const rowColorB = new THREE.Color(0xffb74d);

  function layoutBlocks(rows, cols) {
    let n = 0;
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        dummy.position.set(
          (c - (cols - 1) / 2) * PITCH,
          0.122 + ((rows - 1) / 2 - r) * PITCH,
          0.003 + 0.0085,
        );
        dummy.updateMatrix();
        cubes.setMatrixAt(n, dummy.matrix);
        cubes.setColorAt(n, r % 2 === 0 ? rowColorA : rowColorB);
        n++;
      }
    }
    cubes.count = n;
    cubes.instanceMatrix.needsUpdate = true;
    if (cubes.instanceColor) cubes.instanceColor.needsUpdate = true;
    cubes.computeBoundingBox();
    cubes.computeBoundingSphere();
  }

  // ---------- Progress orbs (one per question) ----------
  const orbGeo = new THREE.SphereGeometry(0.014, 24, 12);
  const orbs = [];
  for (let i = 0; i < TOTAL; i++) {
    const orb = new THREE.Mesh(
      orbGeo,
      new THREE.MeshStandardMaterial({ color: 0x555b66, emissive: 0x000000, roughness: 0.4 }),
    );
    orb.name = 'ProgressOrb' + (i + 1);
    orb.position.set(0.12 + (i - 2) * 0.05, 0.06, 0.12);
    root.add(orb);
    orbs.push(orb);
  }

  function setOrb(i, state) {
    const m = orbs[i].material;
    if (state === 'pending') { m.color.setHex(0x555b66); m.emissive.setHex(0x000000); }
    else if (state === 'current') { m.color.setHex(0xffd166); m.emissive.setHex(0x7a5a00); }
    else if (state === 'correct') { m.color.setHex(0x2e9e5b); m.emissive.setHex(0x0f5a2c); }
    else { m.color.setHex(0xc8443c); m.emissive.setHex(0x6a1712); }
  }

  // ---------- Quiz logic ----------
  function shuffle(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      const t = arr[i]; arr[i] = arr[j]; arr[j] = t;
    }
    return arr;
  }

  function makeQuestions() {
    const list = [];
    const used = {};
    while (list.length < TOTAL) {
      const a = 2 + Math.floor(Math.random() * 8); // 2..9
      const b = 2 + Math.floor(Math.random() * 8); // 2..9
      const key = Math.min(a, b) + 'x' + Math.max(a, b);
      if (used[key]) continue;
      used[key] = true;
      const correct = a * b;
      const pool = [a * (b + 1), a * (b - 1), (a + 1) * b, (a - 1) * b,
        correct + 10, correct - 10, correct + 2, correct - 2, correct + 1];
      const distractors = [];
      shuffle(pool);
      for (let i = 0; i < pool.length && distractors.length < 3; i++) {
        const v = pool[i];
        if (v > 0 && v !== correct && distractors.indexOf(v) === -1) distractors.push(v);
      }
      const options = shuffle([correct, distractors[0], distractors[1], distractors[2]]);
      list.push({ a, b, correct, options });
    }
    return list;
  }

  let questions = makeQuestions();
  let index = 0;
  let score = 0;
  let phase = 'ask'; // 'ask' | 'answered' | 'done'
  let pop = 0;

  function showQuestion() {
    const q = questions[index];
    phase = 'ask';
    panel.set('progress', { text: 'Question ' + (index + 1) + ' of ' + TOTAL });
    panel.set('question', { text: q.a + ' × ' + q.b + ' = ?' });
    for (let i = 0; i < 4; i++) {
      panel.set('t' + i, { text: String(q.options[i]) });
      panel.set('a' + i, { backgroundColor: COLORS.idle });
    }
    panel.set('feedback', { text: 'Hint: grab the blocks and count ' + q.a + ' rows of ' + q.b + '.', color: '#d7dbe2' });
    panel.set('nextText', { text: index === TOTAL - 1 ? 'See results' : 'Next question' });
    panel.set('next', { backgroundColor: COLORS.dim });
    setOrb(index, 'current');
    layoutBlocks(q.a, q.b);
  }

  function startQuiz() {
    questions = makeQuestions();
    index = 0;
    score = 0;
    for (let i = 0; i < TOTAL; i++) setOrb(i, 'pending');
    panel.set('score', { text: 'Score: 0 / ' + TOTAL });
    panel.set('row0', { display: 'flex' });
    panel.set('row1', { display: 'flex' });
    showQuestion();
  }

  function answer(i) {
    if (phase !== 'ask') return;
    const q = questions[index];
    const correctIdx = q.options.indexOf(q.correct);
    phase = 'answered';
    for (let k = 0; k < 4; k++) panel.set('a' + k, { backgroundColor: COLORS.dim });
    panel.set('a' + correctIdx, { backgroundColor: COLORS.correct });
    const fact = q.a + ' × ' + q.b + ' = ' + q.correct;
    if (i === correctIdx) {
      score++;
      pop = 1;
      setOrb(index, 'correct');
      panel.set('feedback', { text: 'Correct! ' + fact, color: '#7be0a0' });
    } else {
      panel.set('a' + i, { backgroundColor: COLORS.wrong });
      setOrb(index, 'wrong');
      panel.set('feedback', { text: 'Not quite. ' + fact, color: '#ff9a92' });
    }
    panel.set('score', { text: 'Score: ' + score + ' / ' + TOTAL });
    panel.set('next', { backgroundColor: COLORS.idle });
  }

  function showResults() {
    phase = 'done';
    panel.set('progress', { text: 'Quiz complete' });
    panel.set('question', { text: score + ' / ' + TOTAL + ' correct' });
    panel.set('row0', { display: 'none' });
    panel.set('row1', { display: 'none' });
    let msg = 'Keep practicing - you will get there!';
    if (score === TOTAL) msg = 'Perfect score! Amazing work!';
    else if (score >= 3) msg = 'Great work! Try again for a perfect score.';
    panel.set('feedback', { text: msg, color: '#ffd166' });
    panel.set('nextText', { text: 'Play again' });
    panel.set('next', { backgroundColor: COLORS.idle });
    if (score === TOTAL) pop = 1;
  }

  panel.on('a0', 'click', () => answer(0));
  panel.on('a1', 'click', () => answer(1));
  panel.on('a2', 'click', () => answer(2));
  panel.on('a3', 'click', () => answer(3));
  panel.on('next', 'click', () => {
    if (phase === 'ask') {
      panel.set('feedback', { text: 'Pick an answer first.', color: '#ffd166' });
    } else if (phase === 'answered') {
      if (index < TOTAL - 1) { index++; showQuestion(); }
      else showResults();
    } else {
      startQuiz();
    }
  });

  startQuiz();

  return {
    root,
    update(time, delta) {
      // Pulse the orb of the current question.
      for (let i = 0; i < TOTAL; i++) {
        const active = phase !== 'done' && i === index;
        const s = active ? 1 + 0.18 * Math.sin(time * 4) : 1;
        orbs[i].scale.setScalar(s);
      }
      // Small celebratory bounce of the block board on a correct answer.
      if (pop > 0) pop = Math.max(0, pop - delta * 2);
      if (!isGrabbed(blocks)) {
        blocks.scale.setScalar(1 + 0.08 * Math.sin(pop * Math.PI));
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Model parameters (B-DNA proportions) ----------
  const SEQ = 'ATGCGTACCTGAAGCTTGCAT';            // strand 1, read 5' -> 3' (bottom to top)
  const COMP = { A: 'T', T: 'A', G: 'C', C: 'G' };
  const N = SEQ.length;                            // 21 base pairs = 2 full turns
  const RISE = 0.015;                              // metres per base pair (models 0.34 nm)
  const HEIGHT = RISE * (N - 1);
  const TWIST = (Math.PI * 2) / 10.5;              // ~10.5 base pairs per turn
  const R = 0.045;                                 // helix radius (models ~1 nm)
  const GROOVE = 2.4;                              // strand phase offset -> major / minor grooves
  const GAP = 0.006;                               // gap between paired bases (hydrogen bonds)

  // Right-handed helix around +Y
  const helixPoint = (idx, phase, target) => {
    const th = idx * TWIST + phase;
    return target.set(R * Math.sin(th), -HEIGHT / 2 + idx * RISE, R * Math.cos(th));
  };

  // ---------- Pedestal (scenery, marks the home spot) ----------
  const HOME = new THREE.Vector3(-0.14, 0.23, 0.05);
  const pedestal = new THREE.Mesh(
    new THREE.CylinderGeometry(0.06, 0.068, 0.012, 32),
    new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.7, metalness: 0.2 }),
  );
  pedestal.name = 'Pedestal';
  pedestal.position.set(HOME.x, 0.006, HOME.z);
  root.add(pedestal);

  // ---------- Grabbable helix ----------
  const helix = new THREE.Group();
  helix.name = 'DNA double helix';
  helix.position.copy(HOME);
  root.add(helix);

  const spinner = new THREE.Group();               // spins around the helix's own axis
  helix.add(spinner);

  const strandMatA = new THREE.MeshStandardMaterial({ color: 0xe8eaf0, roughness: 0.45, metalness: 0.1 });
  const strandMatB = new THREE.MeshStandardMaterial({ color: 0x7f8aa3, roughness: 0.45, metalness: 0.1 });

  const up = new THREE.Vector3(0, 1, 0);
  const tmpV = new THREE.Vector3();
  const sugarGeo = new THREE.SphereGeometry(0.0085, 12, 8);
  const capGeo = new THREE.SphereGeometry(0.0095, 12, 8);
  const coneGeo = new THREE.ConeGeometry(0.012, 0.03, 12);
  const m4 = new THREE.Matrix4();
  const quat = new THREE.Quaternion();
  const quatI = new THREE.Quaternion();
  const scl = new THREE.Vector3();

  function buildStrand(phase, material, fivePrimeAtBottom, label) {
    const pts = [];
    for (let k = -2; k <= (N - 1) * 4 + 2; k++) {
      pts.push(helixPoint(k / 4, phase, new THREE.Vector3()));
    }
    const curve = new THREE.CatmullRomCurve3(pts);
    const tube = new THREE.Mesh(new THREE.TubeGeometry(curve, 168, 0.0055, 8, false), material);
    tube.name = label + ' sugar-phosphate backbone';
    spinner.add(tube);

    // Sugar-phosphate beads, one per nucleotide
    const sugars = new THREE.InstancedMesh(sugarGeo, material, N);
    sugars.name = label + ' nucleotides';
    for (let i = 0; i < N; i++) {
      helixPoint(i, phase, tmpV);
      m4.compose(tmpV, quatI, scl.set(1, 1, 1));
      sugars.setMatrixAt(i, m4);
    }
    sugars.instanceMatrix.needsUpdate = true;
    sugars.computeBoundingBox();
    sugars.computeBoundingSphere();
    spinner.add(sugars);

    // Cone marks the 3' end, round cap marks the 5' end
    const t3 = fivePrimeAtBottom ? 1 : 0;
    const t5 = fivePrimeAtBottom ? 0 : 1;
    const tangent = curve.getTangent(t3, new THREE.Vector3());
    if (!fivePrimeAtBottom) tangent.negate();
    const cone = new THREE.Mesh(coneGeo, material);
    cone.name = label + " 3' end";
    cone.position.copy(curve.getPoint(t3, tmpV)).addScaledVector(tangent, 0.012);
    cone.quaternion.setFromUnitVectors(up, tangent);
    spinner.add(cone);

    const cap = new THREE.Mesh(capGeo, material);
    cap.name = label + " 5' end";
    cap.position.copy(curve.getPoint(t5, tmpV));
    spinner.add(cap);
  }

  buildStrand(0, strandMatA, true, 'Strand 1');        // runs 5' -> 3' upward
  buildStrand(GROOVE, strandMatB, false, 'Strand 2');  // antiparallel: 5' -> 3' downward

  // ---------- Base pairs ----------
  const baseColors = {
    A: new THREE.Color(0x3ecf6a),
    T: new THREE.Color(0xe5484d),
    G: new THREE.Color(0xf2c744),
    C: new THREE.Color(0x3b82f6),
  };
  const dimColor = new THREE.Color(0x30343b);

  const bases = new THREE.InstancedMesh(
    new THREE.CylinderGeometry(0.005, 0.005, 1, 8),
    new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.5 }),
    N * 2,
  );
  bases.name = 'Bases';

  let beadCount = 0;
  for (let i = 0; i < N; i++) beadCount += (SEQ[i] === 'A' || SEQ[i] === 'T') ? 2 : 3;
  const beads = new THREE.InstancedMesh(
    new THREE.SphereGeometry(0.0017, 8, 6),
    new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 0xffffff, emissiveIntensity: 0.6 }),
    beadCount,
  );
  beads.name = 'Hydrogen bonds';

  const pa = new THREE.Vector3();
  const pb = new THREE.Vector3();
  const dir = new THREE.Vector3();
  const side = new THREE.Vector3();
  const mid = new THREE.Vector3();
  let beadIdx = 0;
  for (let i = 0; i < N; i++) {
    helixPoint(i, 0, pa);
    helixPoint(i, GROOVE, pb);
    dir.subVectors(pb, pa);
    const len = dir.length();
    dir.divideScalar(len);
    quat.setFromUnitVectors(up, dir);

    const b1 = SEQ[i];
    const purineFirst = b1 === 'A' || b1 === 'G';      // purines (2 rings) are longer
    const split = len * (purineFirst ? 0.58 : 0.42);
    const l1 = split - GAP / 2;
    const l2 = len - split - GAP / 2;

    mid.copy(pa).addScaledVector(dir, l1 / 2);
    m4.compose(mid, quat, scl.set(1, l1, 1));
    bases.setMatrixAt(i * 2, m4);

    mid.copy(pb).addScaledVector(dir, -l2 / 2);
    m4.compose(mid, quat, scl.set(1, l2, 1));
    bases.setMatrixAt(i * 2 + 1, m4);

    // Hydrogen bonds: 2 for A-T, 3 for G-C
    side.crossVectors(dir, up).normalize();
    const nb = (b1 === 'A' || b1 === 'T') ? 2 : 3;
    for (let j = 0; j < nb; j++) {
      const off = (j - (nb - 1) / 2) * 0.0042;
      mid.copy(pa).addScaledVector(dir, split).addScaledVector(side, off);
      m4.compose(mid, quatI, scl.set(1, 1, 1));
      beads.setMatrixAt(beadIdx++, m4);
    }
  }
  bases.instanceMatrix.needsUpdate = true;
  beads.instanceMatrix.needsUpdate = true;
  bases.computeBoundingBox();
  bases.computeBoundingSphere();
  beads.computeBoundingBox();
  beads.computeBoundingSphere();
  spinner.add(bases);
  spinner.add(beads);

  function applyHighlight(mode) {
    for (let i = 0; i < N; i++) {
      const b1 = SEQ[i];
      const isAT = b1 === 'A' || b1 === 'T';
      const on = mode === 0 || (mode === 1 && isAT) || (mode === 2 && !isAT);
      bases.setColorAt(i * 2, on ? baseColors[b1] : dimColor);
      bases.setColorAt(i * 2 + 1, on ? baseColors[COMP[b1]] : dimColor);
    }
    bases.instanceColor.needsUpdate = true;
  }
  applyHighlight(0);

  traits(helix, { grab: true });

  // ---------- Info panel ----------
  const panel = ui(`
    <style>
      .card { flex-direction: column; gap: 12px; width: 540px; padding-top: 20px; padding-bottom: 20px;
              padding-left: 24px; padding-right: 24px; border-radius: 20px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .hint { color: #9fd0ff; font-size: 21px; }
      .body { color: #d7dbe2; font-size: 22px; }
      .row { flex-direction: row; gap: 12px; align-items: center; }
      .item { flex-direction: row; gap: 8px; align-items: center; width: 240px; }
      .dotA { width: 22px; height: 22px; border-radius: 11px; background-color: #3ecf6a; }
      .dotT { width: 22px; height: 22px; border-radius: 11px; background-color: #e5484d; }
      .dotG { width: 22px; height: 22px; border-radius: 11px; background-color: #f2c744; }
      .dotC { width: 22px; height: 22px; border-radius: 11px; background-color: #3b82f6; }
      .legend { color: #ffffff; font-size: 20px; }
      .btn { width: 240px; align-items: center; justify-content: center; padding-top: 10px; padding-bottom: 10px;
             padding-left: 12px; padding-right: 12px; border-radius: 12px; background-color: #2f6fdb; }
      .btn2 { width: 240px; align-items: center; justify-content: center; padding-top: 10px; padding-bottom: 10px;
              padding-left: 12px; padding-right: 12px; border-radius: 12px; background-color: #3a4050; }
      .btn-text { color: #ffffff; font-size: 21px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">DNA Double Helix</span>
      <span class="hint">Pinch the helix to pick it up, then turn your hand to look at it from any side.</span>
      <div class="row">
        <div class="item"><div class="dotA"></div><span class="legend">A  Adenine</span></div>
        <div class="item"><div class="dotT"></div><span class="legend">T  Thymine</span></div>
      </div>
      <div class="row">
        <div class="item"><div class="dotG"></div><span class="legend">G  Guanine</span></div>
        <div class="item"><div class="dotC"></div><span class="legend">C  Cytosine</span></div>
      </div>
      <span class="body" id="fact">Two strands wind around each other in a right-handed spiral. This model shows 21 base pairs: two full turns.</span>
      <div class="row">
        <button class="btn" id="next"><span class="btn-text">Next fact</span></button>
        <button class="btn" id="hl"><span class="btn-text" id="hl-text">Show: all pairs</span></button>
      </div>
      <div class="row">
        <button class="btn2" id="spin"><span class="btn-text" id="spin-text">Spin: on</span></button>
        <button class="btn2" id="reset"><span class="btn-text">Put back</span></button>
      </div>
    </div>`, { width: 0.36, position: [0.2, 0.23, 0], rotationY: -0.35 });
  root.add(panel.object3D);

  const facts = [
    'The two rails are sugar-phosphate backbones. The rungs are pairs of bases that carry the genetic code.',
    'A always pairs with T (2 hydrogen bonds) and G with C (3 hydrogen bonds). Look closely for the white beads between the bases.',
    "The strands are antiparallel: the light strand runs 5' to 3' upward, the dark strand runs 5' to 3' downward. Cones mark the 3' ends.",
    'Turn the helix: the gaps between the strands are uneven. The wide one is the major groove, the narrow one the minor groove.',
    'Real B-DNA is about 2 nm wide, with about 10.5 base pairs per turn and 0.34 nm between neighbouring pairs.',
    'Purines (A, G) have two rings and pyrimidines (T, C) have one, so the longer half of each rung is the purine.',
    'A human genome holds about 3.1 billion base pairs. Stretched out, the DNA in one cell would be roughly 2 m long.',
  ];
  let factIndex = -1;
  panel.on('next', 'click', () => {
    factIndex = (factIndex + 1) % facts.length;
    panel.set('fact', { text: facts[factIndex] });
  });

  const hlLabels = ['Show: all pairs', 'Show: A-T only', 'Show: G-C only'];
  const hlInfo = [
    'All 21 base pairs are shown: 11 A-T pairs and 10 G-C pairs.',
    'A-T pairs (green + red) are joined by 2 hydrogen bonds, so they are easier to pull apart.',
    'G-C pairs (yellow + blue) are joined by 3 hydrogen bonds. G-C rich DNA needs more heat to separate.',
  ];
  let hlMode = 0;
  panel.on('hl', 'click', () => {
    hlMode = (hlMode + 1) % 3;
    applyHighlight(hlMode);
    panel.set('hl-text', { text: hlLabels[hlMode] });
    panel.set('fact', { text: hlInfo[hlMode] });
  });

  let spinning = true;
  panel.on('spin', 'click', () => {
    spinning = !spinning;
    panel.set('spin-text', { text: spinning ? 'Spin: on' : 'Spin: off' });
  });

  panel.on('reset', 'click', () => {
    if (isGrabbed(helix)) return;
    helix.position.copy(HOME);
    helix.quaternion.identity();
    spinner.rotation.y = 0;
  });

  return {
    root,
    update(time, delta) {
      if (!spinning || isGrabbed(helix)) return;   // never fight the user's hand
      spinner.rotation.y += delta * 0.25;          // slow spin about the helix's own axis
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---- Helix parameters (model is not to scale) ----
  const N = 24;                    // base pairs
  const RADIUS = 0.035;
  const RISE = 0.0125;             // m per base pair -> 0.3 m tall
  const TWIST = (Math.PI * 2) / 10; // 10 base pairs per turn
  const OFFSET = 2.4;              // strand 2 phase offset (leaves major/minor grooves)
  const seq = 'ATGCGTACCTAGGCTTAACGGATC';
  const comp = { A: 'T', T: 'A', G: 'C', C: 'G' };
  const baseColors = { A: 0x4caf50, T: 0xe05045, G: 0xf2c230, C: 0x3b82f6 };

  const helix = new THREE.Group();
  helix.name = 'DNA double helix';
  helix.position.set(0, 0.22, 0);
  root.add(helix);

  // Translucent hit volume so the helix is easy to pinch
  const hit = new THREE.Mesh(
    new THREE.CylinderGeometry(0.055, 0.055, 0.33, 20, 1),
    new THREE.MeshStandardMaterial({ color: 0x9ec9ff, transparent: true, opacity: 0.07, depthWrite: false }),
  );
  hit.name = 'Grab handle';
  helix.add(hit);

  // ---- Backbone spheres (two strands) ----
  const sphereGeo = new THREE.SphereGeometry(0.0085, 16, 12);
  const strandMats = [
    new THREE.MeshStandardMaterial({ color: 0xd5dbe6, roughness: 0.4 }),
    new THREE.MeshStandardMaterial({ color: 0xb792f0, roughness: 0.4 }),
  ];
  const spheres = [
    new THREE.InstancedMesh(sphereGeo, strandMats[0], N),
    new THREE.InstancedMesh(sphereGeo, strandMats[1], N),
  ];
  spheres[0].name = 'Strand 1 backbone';
  spheres[1].name = 'Strand 2 backbone';
  helix.add(spheres[0], spheres[1]);

  // ---- Rods (backbone links and bases) ----
  const rodGeo = new THREE.CylinderGeometry(0.0045, 0.0045, 1, 8);
  const linkGeo = new THREE.CylinderGeometry(0.0045, 0.0045, 1, 8);
  const links = [
    new THREE.InstancedMesh(linkGeo, strandMats[0], N),
    new THREE.InstancedMesh(linkGeo, strandMats[1], N),
  ];
  helix.add(links[0], links[1]);

  const baseMeshes = {};
  const baseCounts = { A: 0, T: 0, G: 0, C: 0 };
  for (const k of ['A', 'T', 'G', 'C']) {
    const m = new THREE.InstancedMesh(
      new THREE.CylinderGeometry(0.0055, 0.0055, 1, 10),
      new THREE.MeshStandardMaterial({ color: baseColors[k], roughness: 0.5 }),
      N,
    );
    m.name = 'Base ' + k;
    baseMeshes[k] = m;
    helix.add(m);
  }

  const Y = new THREE.Vector3(0, 1, 0);
  const tmpM = new THREE.Matrix4();
  const tmpQ = new THREE.Quaternion();
  const tmpS = new THREE.Vector3();
  const tmpDir = new THREE.Vector3();
  const tmpMid = new THREE.Vector3();

  function placeRod(mesh, index, a, b) {
    tmpDir.subVectors(b, a);
    const len = tmpDir.length();
    tmpDir.normalize();
    tmpQ.setFromUnitVectors(Y, tmpDir);
    tmpMid.addVectors(a, b).multiplyScalar(0.5);
    tmpS.set(1, len, 1);
    tmpM.compose(tmpMid, tmpQ, tmpS);
    mesh.setMatrixAt(index, tmpM);
  }

  const p1 = [];
  const p2 = [];
  for (let i = 0; i < N; i++) {
    const y = (i - (N - 1) / 2) * RISE;
    const a1 = i * TWIST;
    const a2 = a1 + OFFSET;
    p1.push(new THREE.Vector3(Math.cos(a1) * RADIUS, y, Math.sin(a1) * RADIUS));
    p2.push(new THREE.Vector3(Math.cos(a2) * RADIUS, y, Math.sin(a2) * RADIUS));
  }

  const identQ = new THREE.Quaternion();
  const one = new THREE.Vector3(1, 1, 1);
  const mid = new THREE.Vector3();
  for (let i = 0; i < N; i++) {
    tmpM.compose(p1[i], identQ, one);
    spheres[0].setMatrixAt(i, tmpM);
    tmpM.compose(p2[i], identQ, one);
    spheres[1].setMatrixAt(i, tmpM);

    if (i < N - 1) {
      placeRod(links[0], i, p1[i], p1[i + 1]);
      placeRod(links[1], i, p2[i], p2[i + 1]);
    }

    // Base pair: each half is coloured by its own base
    const b1 = seq[i];
    const b2 = comp[b1];
    mid.addVectors(p1[i], p2[i]).multiplyScalar(0.5);
    placeRod(baseMeshes[b1], baseCounts[b1]++, p1[i], mid);
    placeRod(baseMeshes[b2], baseCounts[b2]++, mid, p2[i]);
  }
  links[0].count = N - 1;
  links[1].count = N - 1;
  for (const k of ['A', 'T', 'G', 'C']) baseMeshes[k].count = baseCounts[k];

  traits(helix, { grab: true });

  // ---- Info panel ----
  const panel = ui(`
    <style>
      .card { flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 21px; }
      .row { flex-direction: row; align-items: center; gap: 10px; }
      .dot { width: 22px; height: 22px; border-radius: 11px; }
      .legend { color: #ffffff; font-size: 20px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #2f6fdb; align-items: center; justify-content: center; }
      .btn2 { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
              border-radius: 12px; background-color: #3a3f48; align-items: center; justify-content: center; }
      .btn-text { color: #ffffff; font-size: 21px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">DNA double helix</span>
      <span class="body">Pinch the helix to pick it up and turn it.</span>
      <div class="row"><div class="dot" style="background-color: #4caf50"></div><span class="legend">Adenine (A) pairs with</span></div>
      <div class="row"><div class="dot" style="background-color: #e05045"></div><span class="legend">Thymine (T): 2 H-bonds</span></div>
      <div class="row"><div class="dot" style="background-color: #f2c230"></div><span class="legend">Guanine (G) pairs with</span></div>
      <div class="row"><div class="dot" style="background-color: #3b82f6"></div><span class="legend">Cytosine (C): 3 H-bonds</span></div>
      <span class="body" id="fact">Silver and purple ribbons are the sugar-phosphate backbones.</span>
      <button class="btn" id="next"><span class="btn-text">Next fact</span></button>
      <button class="btn2" id="spin"><span class="btn-text" id="spinText">Auto-spin: on</span></button>
    </div>`, { width: 0.34, position: [0.3, 0.2, 0], rotationY: -0.35 });
  root.add(panel.object3D);

  const facts = [
    'Each full turn has about 10 base pairs and is about 3.4 nm long.',
    'The two strands run in opposite directions (antiparallel).',
    'Bases pair by shape: A with T, G with C. One strand predicts the other.',
    'Watson and Crick proposed this structure in 1953, using X-ray data from Rosalind Franklin.',
    'The human genome has about 3.2 billion base pairs.',
    'This model is enlarged and simplified; real DNA is only about 2 nm wide.',
  ];
  let fi = -1;
  panel.on('next', 'click', () => {
    fi = (fi + 1) % facts.length;
    panel.set('fact', { text: facts[fi] });
  });

  let spinning = true;
  panel.on('spin', 'click', () => {
    spinning = !spinning;
    panel.set('spinText', { text: spinning ? 'Auto-spin: on' : 'Auto-spin: off' });
  });

  return {
    root,
    update(time, delta) {
      if (isGrabbed(helix)) return;
      if (spinning) helix.rotation.y += delta * 0.3;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

