  const appleGeo = new THREE.SphereGeometry(0.035, 28, 14);
  appleGeo.scale(1, 0.9, 1);
  const apple = new THREE.Mesh(appleGeo, new THREE.MeshStandardMaterial({ color: 0xd62828, roughness: 0.45 }));
  apple.name = 'Apple';
  const appleStem = new THREE.Mesh(new THREE.CylinderGeometry(0.003, 0.003, 0.02, 6), stemMat);
  appleStem.position.y = 0.036;
  apple.add(appleStem);
  const leafGeo = new THREE.SphereGeometry(0.012, 8, 6);
  leafGeo.scale(1, 0.25, 0.5);
  const appleLeaf = new THREE.Mesh(leafGeo, leafMat);
  appleLeaf.position.set(0.012, 0.042, 0);
