  const orange = new THREE.Mesh(
    new THREE.SphereGeometry(0.035, 28, 14),
    new THREE.MeshStandardMaterial({ color: 0xff8c1a, roughness: 0.85 }),
  );
  orange.name = 'Orange';
  const orangeNub = new THREE.Mesh(new THREE.CylinderGeometry(0.005, 0.005, 0.004, 8), leafMat);
  orangeNub.position.y = 0.035;
  orange.add(orangeNub);

  // Banana (curved tube lying flat)
  const BAN_R = 0.07, BAN_ARC = 1.6, BAN_TUBE = 0.016;
  const bananaGeo = new THREE.TorusGeometry(BAN_R, BAN_TUBE, 10, 18, BAN_ARC);
  bananaGeo.rotateZ(-(Math.PI / 2 + BAN_ARC / 2));
  bananaGeo.translate(0, BAN_R, 0);
  bananaGeo.rotateX(-Math.PI / 2);
  const banana = new THREE.Mesh(bananaGeo, new THREE.MeshStandardMaterial({ color: 0xffd92e, roughness: 0.6 }));
  banana.name = 'Banana';
  const tipGeo = new THREE.SphereGeometry(0.0165, 10, 8);
  const tipX = BAN_R * Math.sin(BAN_ARC / 2);
  const tipZ = -(BAN_R - BAN_R * Math.cos(BAN_ARC / 2));
  const tipA = new THREE.Mesh(tipGeo, stemMat);
  tipA.position.set(tipX, 0, tipZ);
  banana.add(tipA);
  const tipB = new THREE.Mesh(tipGeo, stemMat);
  tipB.position.set(-tipX, 0, tipZ);
  banana.add(tipB);

  const fruits = [
    {
      obj: apple, label: 'Apple', cents: 50, rowId: 'row-apple', restY: 0.032,
      home: new THREE.Vector3(-0.34, 0.032, 0.08),
      slot: new THREE.Vector3(BASKET_X - 0.04, 0.038, BASKET_Z + 0.025), slotRotY: 0,
      inBasket: false, wasGrabbed: false,
    },
    {
      obj: orange, label: 'Orange', cents: 75, rowId: 'row-orange', restY: 0.035,
      home: new THREE.Vector3(-0.22, 0.035, 0.08),
      slot: new THREE.Vector3(BASKET_X + 0.04, 0.041, BASKET_Z + 0.025), slotRotY: 0,
      inBasket: false, wasGrabbed: false,
    },
    {
      obj: banana, label: 'Banana', cents: 25, rowId: 'row-banana', restY: 0.016,
      home: new THREE.Vector3(-0.07, 0.016, 0.08),
      slot: new THREE.Vector3(BASKET_X, 0.06, BASKET_Z - 0.045), slotRotY: Math.PI,
      inBasket: false, wasGrabbed: false,
    },
  ];

  for (const f of fruits) {
    f.obj.position.copy(f.home);
    root.add(f.obj);
    traits(f.obj, { grab: true });
  }

  // ---------- Panel ----------
  const panel = ui(`
    <style>
      .card { flex-direction: column; gap: 10px; width: 500px; padding-top: 20px; padding-bottom: 20px;
              padding-left: 24px; padding-right: 24px; border-radius: 20px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .hint { color: #b9c0cb; font-size: 20px; }
      .row { flex-direction: row; justify-content: space-between; align-items: center;
             padding-top: 8px; padding-bottom: 8px; padding-left: 14px; padding-right: 14px;
             border-radius: 10px; background-color: #2a2e35; }
      .name { color: #ffffff; font-size: 24px; }
      .price { color: #d7dbe2; font-size: 24px; }
      .totalrow { flex-direction: row; justify-content: space-between; align-items: center;
                  padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px;
                  border-radius: 10px; border-width: 2px; border-color: #4dff88; background-color: #1a1d22; }
      .total-label { color: #ffffff; font-size: 28px; font-weight: 700; }
      .total { color: #4dff88; font-size: 32px; font-weight: 700; }
      .btn { flex-direction: row; justify-content: center; align-items: center;
             padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Fruit Basket</span>
      <span class="hint" id="hint">Pinch a fruit and drop it in the basket.</span>
      <div class="row" id="row-apple"><span class="name">Apple</span><span class="price">$0.50</span></div>
      <div class="row" id="row-orange"><span class="name">Orange</span><span class="price">$0.75</span></div>
      <div class="row" id="row-banana"><span class="name">Banana</span><span class="price">$0.25</span></div>
      <div class="totalrow"><span class="total-label" id="count">Basket total (0 of 3)</span><span class="total" id="total">$0.00</span></div>
      <button class="btn" id="reset"><span class="btn-text">Empty basket</span></button>
    </div>`, { width: 0.36, position: [-0.05, 0.3, -0.14] });
  root.add(panel.object3D);

  function refresh() {
    let cents = 0, count = 0;
    for (const f of fruits) {
      if (f.inBasket) { cents += f.cents; count++; }
      panel.set(f.rowId, { backgroundColor: f.inBasket ? '#2e6b3e' : '#2a2e35' });
    }
    panel.set('total', { text: '$' + (cents / 100).toFixed(2) });
    panel.set('count', { text: 'Basket total (' + count + ' of 3)' });
    panel.set('hint', {
      text: count === 3 ? 'All three fruits are in the basket!'
        : count === 0 ? 'Pinch a fruit and drop it in the basket.'
        : 'Take a fruit out and the total goes down.',
    });
  }

  panel.on('reset', 'click', () => {
    for (const f of fruits) {
      if (isGrabbed(f.obj)) continue;
      f.inBasket = false;
      f.obj.position.copy(f.home);
      f.obj.rotation.set(0, 0, 0);
    }
    refresh();
  });

  refresh();

  // ---------- Per-frame logic ----------
  const tmp = new THREE.Vector3();

  function localPos(obj) {
    obj.getWorldPosition(tmp);
    root.worldToLocal(tmp);
    return tmp;
  }

  function overBasket(p) {
    const dx = p.x - BASKET_X, dz = p.z - BASKET_Z;
    return dx * dx + dz * dz < DROP_RADIUS * DROP_RADIUS && p.y < 0.45;
  }

  return {
    root,
    update() {
      let dirty = false;
      let hovering = false;

      for (let i = 0; i < fruits.length; i++) {
        const f = fruits[i];
        const held = isGrabbed(f.obj);

        if (held) {
          // Lifting a fruit takes it out of the basket.
          if (f.inBasket) { f.inBasket = false; dirty = true; }
          if (overBasket(localPos(f.obj))) hovering = true;
        } else if (f.wasGrabbed) {
          // Just released: decide where it lands.
          const p = localPos(f.obj);
          if (overBasket(p)) {
            f.inBasket = true;
            f.obj.position.copy(f.slot);
            f.obj.rotation.set(0, f.slotRotY, 0);
          } else {
            f.inBasket = false;
            let x = Math.min(0.37, Math.max(-0.37, p.x));
            let z = Math.min(0.25, Math.max(-0.2, p.z));
            // Keep it clear of the basket wall.
            const dx = x - BASKET_X, dz = z - BASKET_Z;
            const d = Math.sqrt(dx * dx + dz * dz);
            if (d < 0.19 && d > 0.0001) {
              x = BASKET_X + (dx / d) * 0.19;
              z = BASKET_Z + (dz / d) * 0.19;
            }
            f.obj.position.set(x, f.restY, z);
            f.obj.rotation.set(0, 0, 0);
          }
          dirty = true;
        }
        f.wasGrabbed = held;
      }

      rimMat.emissiveIntensity = hovering ? 0.9 : 0;
      if (dirty) refresh();
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Quiz data ----------
  const questions = [[6, 7], [8, 4], [9, 6], [7, 8], [5, 9]];
  const TOTAL = questions.length;

  function makeChoices(a, b, qi) {
    const correct = a * b;
    const cands = [a * (b + 1), a * (b - 1), (a + 1) * b, (a - 1) * b, a + b, correct + 10];
    const wrong = [];
    for (const c of cands) {
      if (c !== correct && wrong.indexOf(c) === -1) wrong.push(c);
      if (wrong.length === 3) break;
    }
    const pos = (qi * 3 + 1) % 4;
    const choices = wrong.slice();
    choices.splice(pos, 0, correct);
    return choices;
  }

  // ---------- 3D: dot-array visual ----------
  const plate = new THREE.Mesh(
    new THREE.BoxGeometry(0.17, 0.012, 0.17),
    new THREE.MeshStandardMaterial({ color: 0x3a3f4a, roughness: 0.7 }),
  );
  plate.name = 'ArrayBoard';
  plate.position.set(-0.2, 0.006, 0.17);
  root.add(plate);
  traits(plate, { grab: true });

  const MAX_DOTS = 81;
  const dots = new THREE.InstancedMesh(
    new THREE.SphereGeometry(0.006, 16, 10),
    new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.4 }),
    MAX_DOTS,
  );
  dots.name = 'Dots';
  dots.position.y = 0.014;
  plate.add(dots);

  const dummy = new THREE.Object3D();
  const colA = new THREE.Color(0xffc23d);
  const colB = new THREE.Color(0x4fd1c5);

  function showArray(rows, cols) {
    const sp = 0.017;
    let i = 0;
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        dummy.position.set((c - (cols - 1) / 2) * sp, 0, (r - (rows - 1) / 2) * sp);
        dummy.updateMatrix();
        dots.setMatrixAt(i, dummy.matrix);
        dots.setColorAt(i, r % 2 === 0 ? colA : colB);
        i++;
      }
    }
    dots.count = i;
    dots.instanceMatrix.needsUpdate = true;
    if (dots.instanceColor) dots.instanceColor.needsUpdate = true;
  }

  // ---------- 3D: progress orbs ----------
  const orbGeo = new THREE.SphereGeometry(0.016, 20, 12);
  const orbs = [];
  for (let i = 0; i < TOTAL; i++) {
    const m = new THREE.Mesh(
      orbGeo,
      new THREE.MeshStandardMaterial({ color: 0x777c88, emissive: 0x000000, roughness: 0.4 }),
    );
    m.name = 'ProgressOrb' + (i + 1);
    m.position.set(0.12 + (i - 2) * 0.05, 0.02, 0.2);
    root.add(m);
    orbs.push(m);
  }

  // ---------- UI panel ----------
  const panel = ui(`
    <style>
      .card { flex-direction: column; gap: 14px; padding-top: 22px; padding-bottom: 22px;
              padding-left: 26px; padding-right: 26px; border-radius: 22px; background-color: #1f2228; }
      .top { flex-direction: row; justify-content: space-between; align-items: center; }
      .title { color: #ffffff; font-size: 26px; font-weight: 700; }
      .score { color: #ffd54a; font-size: 28px; font-weight: 700; }
      .prog { color: #9aa3b2; font-size: 22px; }
      .qbox { align-items: center; justify-content: center; padding-top: 14px; padding-bottom: 14px;
              border-radius: 16px; background-color: #2a2e35; }
      .q { color: #ffffff; font-size: 54px; font-weight: 700; text-align: center; }
      .hint { color: #9aa3b2; font-size: 20px; text-align: center; }
      .row { flex-direction: row; gap: 14px; justify-content: center; }
      .ans { width: 210px; padding-top: 16px; padding-bottom: 16px; border-radius: 14px;
             background-color: #2f6fdb; align-items: center; justify-content: center; }
      .ans-t { color: #ffffff; font-size: 34px; font-weight: 700; text-align: center; }
      .fb { color: #d7dbe2; font-size: 24px; text-align: center; }
      .next { padding-top: 14px; padding-bottom: 14px; border-radius: 14px; background-color: #8a5cf6;
              align-items: center; justify-content: center; }
      .next-t { color: #ffffff; font-size: 26px; font-weight: 700; }
    </style>
    <div class="card">
      <div class="top">
        <span class="title">Times Tables</span>
        <span class="score" id="score">Score: 0 / 5</span>
      </div>
      <span class="prog" id="prog">Question 1 of 5</span>
      <div class="qbox"><span class="q" id="q">6 × 7 = ?</span></div>
      <span class="hint" id="hint">Count the dots on the board: rows × columns.</span>
      <div class="row" id="r1">
        <button class="ans" id="a0"><span class="ans-t" id="t0">0</span></button>
        <button class="ans" id="a1"><span class="ans-t" id="t1">0</span></button>
      </div>
      <div class="row" id="r2">
        <button class="ans" id="a2"><span class="ans-t" id="t2">0</span></button>
        <button class="ans" id="a3"><span class="ans-t" id="t3">0</span></button>
      </div>
      <span class="fb" id="fb">Poke or pinch an answer.</span>
      <button class="next" id="next"><span class="next-t" id="next-t">Next question</span></button>
    </div>`, { width: 0.5, position: [0, 0.3, -0.02], rotationY: 0 });
  root.add(panel.object3D);

  // ---------- State ----------
  let idx = 0;
  let score = 0;
  let answered = false;
  let finished = false;
  let choices = [];
  const BLUE = '#2f6fdb';

  function resetOrbs() {
    for (const o of orbs) {
      o.material.color.set(0x777c88);
      o.material.emissive.set(0x000000);
    }
  }

  function loadQuestion() {
    const [a, b] = questions[idx];
    choices = makeChoices(a, b, idx);
    answered = false;
    panel.set('q', { text: a + ' × ' + b + ' = ?' });
    panel.set('prog', { text: 'Question ' + (idx + 1) + ' of ' + TOTAL });
    panel.set('hint', { text: a + ' rows of ' + b + ' dots on the board. Count or multiply!' });
    panel.set('fb', { text: 'Poke or pinch an answer.', color: '#d7dbe2' });
    for (let i = 0; i < 4; i++) {
      panel.set('t' + i, { text: String(choices[i]) });
      panel.set('a' + i, { backgroundColor: BLUE });
    }
    panel.set('next', { display: 'none' });
    showArray(a, b);
  }

  function answer(i) {
    if (answered || finished) return;
    answered = true;
    const [a, b] = questions[idx];
    const correct = a * b;
    const right = choices[i] === correct;
    const ci = choices.indexOf(correct);
    panel.set('a' + ci, { backgroundColor: '#2e9e5b' });
    if (right) {
      score++;
      orbs[idx].material.color.set(0x2ecc71);
      panel.set('fb', { text: 'Correct! ' + a + ' × ' + b + ' = ' + correct, color: '#7ee2a0' });
    } else {
      panel.set('a' + i, { backgroundColor: '#c94545' });
      orbs[idx].material.color.set(0xe05555);
      panel.set('fb', { text: 'Not quite. ' + a + ' × ' + b + ' = ' + correct, color: '#ff9a9a' });
    }
    orbs[idx].material.emissive.set(right ? 0x103d20 : 0x401010);
    panel.set('score', { text: 'Score: ' + score + ' / ' + TOTAL });
    panel.set('next-t', { text: idx === TOTAL - 1 ? 'See results' : 'Next question' });
    panel.set('next', { display: 'flex' });
  }

  function showResults() {
    finished = true;
    let msg;
    if (score === TOTAL) msg = 'Perfect! You know your times tables!';
    else if (score >= 3) msg = 'Nice work! A little more practice and you will ace it.';
    else msg = 'Keep practicing, you will get there!';
    panel.set('q', { text: score + ' / ' + TOTAL });
    panel.set('prog', { text: 'Quiz complete' });
    panel.set('hint', { text: 'Final score' });
    panel.set('fb', { text: msg, color: '#ffd54a' });
    panel.set('r1', { display: 'none' });
    panel.set('r2', { display: 'none' });
    panel.set('next-t', { text: 'Play again' });
  }

  function restart() {
    idx = 0;
    score = 0;
    finished = false;
    resetOrbs();
    panel.set('score', { text: 'Score: 0 / ' + TOTAL });
    panel.set('r1', { display: 'flex' });
    panel.set('r2', { display: 'flex' });
    loadQuestion();
  }

  for (let i = 0; i < 4; i++) {
    panel.on('a' + i, 'click', () => answer(i));
  }
  panel.on('next', 'click', () => {
    if (finished) { restart(); return; }
    if (!answered) return;
    if (idx === TOTAL - 1) { showResults(); return; }
    idx++;
    loadQuestion();
  });

  loadQuestion();

  return {
    root,
    update(time) {
      // Pulse the orb for the current question; never touches the grabbable board.
      for (let i = 0; i < TOTAL; i++) {
        const isCurrent = !finished && i === idx && !answered;
        const s = isCurrent ? 1 + Math.sin(time * 4) * 0.12 : 1;
        orbs[i].scale.setScalar(s);
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // The helix lives in its own group so the whole molecule can be grabbed and turned.
  const helix = new THREE.Group();
  helix.name = 'DNA double helix';
  helix.position.set(0, 0.2, 0);
  root.add(helix);

  const N = 16;          // base pairs
  const rise = 0.02;     // metres between base pairs
  const dAng = 0.6;      // radians of twist per base pair (about 34 degrees)
  const R = 0.03;        // helix radius
  const H = (N - 1) * rise;

  const sugarMat = new THREE.MeshStandardMaterial({ color: 0xbfd4e6, roughness: 0.4, metalness: 0.1 });

  // Sugar-phosphate backbones: two strands offset by half a turn.
  const perBase = 12;
  for (let s = 0; s < 2; s++) {
    const pts = [];
    const samples = (N - 1) * perBase;
    for (let k = 0; k <= samples; k++) {
      const u = k / perBase;
      const a = u * dAng + s * Math.PI;
      pts.push(new THREE.Vector3(R * Math.cos(a), u * rise - H / 2, R * Math.sin(a)));
    }
    const curve = new THREE.CatmullRomCurve3(pts);
    const tube = new THREE.Mesh(
      new THREE.TubeGeometry(curve, samples * 2, 0.0045, 10, false),
      sugarMat,
    );
    tube.name = s === 0 ? 'Backbone strand 1' : 'Backbone strand 2';
    helix.add(tube);
  }

  // Base colours
  const baseColor = { A: 0x3cb371, T: 0xe0445a, G: 0xf2c12e, C: 0x3d7bf0 };
  const complement = { A: 'T', T: 'A', G: 'C', C: 'G' };
  const mats = {};
  for (const b of Object.keys(baseColor)) {
    mats[b] = new THREE.MeshStandardMaterial({ color: baseColor[b], roughness: 0.5 });
  }

  // Shared unit cylinder (spans y from -0.5 to 0.5), scaled per rung half.
  const rungGeo = new THREE.CylinderGeometry(0.0038, 0.0038, 1, 10);
  const up = new THREE.Vector3(0, 1, 0);

  function addHalfRung(p0, p1, mat, name) {
    const dir = new THREE.Vector3().subVectors(p1, p0);
    const len = dir.length();
    const mesh = new THREE.Mesh(rungGeo, mat);
    mesh.position.copy(p0).add(p1).multiplyScalar(0.5);
    mesh.quaternion.setFromUnitVectors(up, dir.normalize());
    mesh.scale.set(1, len, 1);
    mesh.name = name;
    helix.add(mesh);
  }

  // Base pairs: each rung is two halves, each coloured by the base on that side.
  const seq = ['A', 'T', 'G', 'C', 'T', 'T', 'A', 'G', 'C', 'G', 'A', 'A', 'T', 'C', 'G', 'T'];
  for (let i = 0; i < N; i++) {
    const y = i * rise - H / 2;
    const a = i * dAng;
    const pA = new THREE.Vector3(R * Math.cos(a), y, R * Math.sin(a));
    const pB = new THREE.Vector3(R * Math.cos(a + Math.PI), y, R * Math.sin(a + Math.PI));
    const mid = new THREE.Vector3().addVectors(pA, pB).multiplyScalar(0.5);
    const b1 = seq[i];
    const b2 = complement[b1];
    addHalfRung(pA, mid, mats[b1], `Base ${i + 1} ${b1}`);
    addHalfRung(mid, pB, mats[b2], `Base ${i + 1} ${b2}`);
  }

  // Make the whole helix grabbable so the user can pick it up and turn it around.
  traits(helix, { grab: true });

  // Reference panel
  const info = ui(`
    <style>
      .card { flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1a1d22; }
      .title { color: #ffffff; font-size: 28px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 20px; }
      .row { flex-direction: row; align-items: center; gap: 10px; }
      .dot { width: 18px; height: 18px; border-radius: 9px; }
      .label { color: #ffffff; font-size: 20px; }
    </style>
    <div class="card">
      <span class="title">DNA double helix</span>
      <span class="body">Pinch the helix to pick it up and turn it.</span>
      <span class="body">Two sugar-phosphate backbones wind around each other. Rungs are base pairs: A pairs with T, G pairs with C.</span>
      <div class="row"><div class="dot" style="background-color: #3cb371;"></div><span class="label">A  Adenine</span></div>
      <div class="row"><div class="dot" style="background-color: #e0445a;"></div><span class="label">T  Thymine</span></div>
      <div class="row"><div class="dot" style="background-color: #f2c12e;"></div><span class="label">G  Guanine</span></div>
      <div class="row"><div class="dot" style="background-color: #3d7bf0;"></div><span class="label">C  Cytosine</span></div>
    </div>`, { width: 0.3, position: [0.27, 0.22, 0], rotationY: -0.35 });
  root.add(info.object3D);

  return { root };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Basket ----------
  const BASKET_X = 0.17, BASKET_Z = 0.02;
  const basket = new THREE.Group();
  basket.name = 'Basket';
  basket.position.set(BASKET_X, 0, BASKET_Z);
  root.add(basket);

  const wickerMat = new THREE.MeshStandardMaterial({ color: 0xb07a3c, roughness: 0.9, side: THREE.DoubleSide });
  const wall = new THREE.Mesh(new THREE.CylinderGeometry(0.11, 0.09, 0.09, 32, 1, true), wickerMat);
  wall.position.y = 0.045;
  basket.add(wall);

  const floorGeo = new THREE.CircleGeometry(0.09, 32);
  floorGeo.rotateX(-Math.PI / 2);
  const floor = new THREE.Mesh(floorGeo, new THREE.MeshStandardMaterial({ color: 0x8a5a28, roughness: 0.95 }));
  floor.position.y = 0.008;
  basket.add(floor);

  const darkWicker = new THREE.MeshStandardMaterial({ color: 0x8a5a28, roughness: 0.9 });
  const rimGeo = new THREE.TorusGeometry(0.11, 0.006, 8, 40);
  rimGeo.rotateX(Math.PI / 2);
  const rim = new THREE.Mesh(rimGeo, darkWicker);
  rim.position.y = 0.09;
  basket.add(rim);
  const ringGeo = new THREE.TorusGeometry(0.1, 0.004, 6, 40);
  ringGeo.rotateX(Math.PI / 2);
  [0.03, 0.06].forEach((y) => {
    const r = new THREE.Mesh(ringGeo, darkWicker);
    r.position.y = y;
    r.scale.setScalar(0.9 + y * 2.2 * 0.5);
    basket.add(r);
  });

  // ---------- Fruits ----------
  const stemMat = new THREE.MeshStandardMaterial({ color: 0x5a3a1a, roughness: 0.9 });
  const leafMat = new THREE.MeshStandardMaterial({ color: 0x3fa34d, roughness: 0.7 });

  // Apple
  const apple = new THREE.Mesh(
    new THREE.SphereGeometry(0.035, 28, 16),
