  const oNub = new THREE.Mesh(new THREE.SphereGeometry(0.006, 8, 6), leafMat);
  oNub.position.y = 0.035;
  orange.add(oNub);

  // Banana (curved tube lying flat, origin at the middle of the arc)
  const R = 0.07, ARC = 1.2;
  const bGeo = new THREE.TorusGeometry(R, 0.014, 10, 24, ARC);
  bGeo.rotateZ(-ARC / 2);
  bGeo.translate(-R, 0, 0);
  bGeo.rotateX(Math.PI / 2);
  const banana = new THREE.Mesh(bGeo, new THREE.MeshStandardMaterial({ color: 0xffd93b, roughness: 0.6 }));
  banana.name = 'Banana';

  const fruits = [
    { mesh: apple,  name: 'Apple',  price: 1.2, r: 0.035, home: [-0.30, 0.05], id: 'apple',  vy: 0, inBasket: false },
    { mesh: orange, name: 'Orange', price: 0.8, r: 0.035, home: [-0.18, 0.05], id: 'orange', vy: 0, inBasket: false },
    { mesh: banana, name: 'Banana', price: 0.6, r: 0.014, home: [-0.05, 0.05], id: 'banana', vy: 0, inBasket: false },
  ];

  fruits.forEach((f, i) => {
    f.mesh.position.set(f.home[0], f.r, f.home[1]);
    root.add(f.mesh);
    traits(f.mesh, { grab: true });
    const a = (i / 3) * Math.PI * 2 + 0.5;
    f.slot = [BASKET_X + Math.cos(a) * 0.04, BASKET_Z + Math.sin(a) * 0.04];
  });

  // ---------- Info panel ----------
  const row = (f) => `
    <div class="row">
      <span class="name" id="n-${f.id}">${f.name}</span>
      <span class="price">$${f.price.toFixed(2)}</span>
      <span class="status" id="s-${f.id}">on desk</span>
    </div>`;

  const panel = ui(`
    <style>
      .card { flex-direction: column; gap: 12px; padding-top: 22px; padding-bottom: 22px;
              padding-left: 26px; padding-right: 26px; border-radius: 20px; background-color: #1f2228; width: 520px; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .hint { color: #b8bec9; font-size: 22px; }
      .row { flex-direction: row; justify-content: space-between; align-items: center; gap: 12px;
             padding-top: 8px; padding-bottom: 8px; padding-left: 14px; padding-right: 14px;
             border-radius: 12px; background-color: #2a2e35; }
      .name { color: #ffffff; font-size: 26px; font-weight: 700; width: 140px; }
      .price { color: #ffd93b; font-size: 26px; width: 100px; }
      .status { color: #8a919c; font-size: 22px; width: 150px; text-align: right; }
      .totalrow { flex-direction: row; justify-content: space-between; align-items: center;
                  padding-top: 10px; padding-bottom: 6px; padding-left: 14px; padding-right: 14px; }
      .totallabel { color: #ffffff; font-size: 30px; font-weight: 700; }
      .total { color: #5be37d; font-size: 38px; font-weight: 700; }
      .btn { padding-top: 12px; padding-bottom: 12px; padding-left: 18px; padding-right: 18px;
             border-radius: 12px; background-color: #2f6fdb; align-items: center; justify-content: center; }
      .btn-text { color: #ffffff; font-size: 24px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Fruit Stand</span>
      <span class="hint">Pinch a fruit and drop it into the basket.</span>
      ${fruits.map(row).join('')}
      <div class="totalrow">
        <span class="totallabel">Total</span>
        <span class="total" id="total">$0.00</span>
      </div>
      <span class="hint" id="count">Basket is empty</span>
      <button class="btn" id="reset"><span class="btn-text">Put fruit back</span></button>
    </div>`, { width: 0.36, position: [-0.12, 0.2, -0.16], rotationY: 0.12 });
  root.add(panel.object3D);

  panel.on('reset', 'click', () => {
    fruits.forEach((f) => {
      f.mesh.position.set(f.home[0], f.r + 0.03, f.home[1]);
      f.vy = 0;
    });
  });

  // ---------- Logic ----------
  let lastKey = '';
  const GRAVITY = 3.0;
  const INSIDE_R = 0.088;

  function refreshUI() {
    let total = 0, count = 0;
    let key = '';
    fruits.forEach((f) => {
      key += f.inBasket ? '1' : '0';
      if (f.inBasket) { total += f.price; count++; }
    });
    if (key === lastKey) return;
    lastKey = key;
    fruits.forEach((f) => {
      panel.set('s-' + f.id, f.inBasket
        ? { text: 'in basket', color: '#5be37d' }
        : { text: 'on desk', color: '#8a919c' });
    });
    panel.set('total', { text: '$' + total.toFixed(2) });
    panel.set('count', {
      text: count === 0 ? 'Basket is empty' : count + (count === 1 ? ' item' : ' items') + ' in basket',
    });
  }
  refreshUI();
  lastKey = ''; // force first sync
  refreshUI();

  return {
    root,
    update(time, delta) {
      const dt = Math.min(delta, 0.05);
      const k = 1 - Math.exp(-3 * dt);
      for (let i = 0; i < fruits.length; i++) {
        const f = fruits[i];
        const m = f.mesh;
        if (isGrabbed(m)) {
          f.vy = 0;
          f.inBasket = false;
          continue;
        }
        const dx = m.position.x - BASKET_X;
        const dz = m.position.z - BASKET_Z;
        const over = Math.sqrt(dx * dx + dz * dz) < INSIDE_R;
        const floorY = (over ? 0.01 : 0) + f.r;

        if (m.position.y > floorY + 0.0005) {
          f.vy -= GRAVITY * dt;
          m.position.y += f.vy * dt;
          if (m.position.y <= floorY) { m.position.y = floorY; f.vy = 0; }
        } else {
          m.position.y = floorY;
          f.vy = 0;
        }

        // Inside the basket: settle gently into a personal slot so fruit don't overlap
        const inside = over && m.position.y < 0.13;
        if (inside && m.position.y <= floorY + 0.01) {
          m.position.x += (f.slot[0] - m.position.x) * k;
          m.position.z += (f.slot[1] - m.position.z) * k;
        }
        f.inBasket = inside;
      }
      refreshUI();
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // Each question: [text, choices, index of correct choice]
  const questions = [
    ['6 × 7 = ?', [42, 36, 48, 49], 0],
    ['8 × 9 = ?', [63, 72, 81, 74], 1],
    ['12 × 4 = ?', [44, 48, 52, 46], 1],
    ['7 × 8 = ?', [54, 56, 63, 58], 1],
    ['9 × 6 = ?', [56, 45, 54, 64], 2],
  ];

  const COLOR_DEFAULT = '#2a2e35';
  const COLOR_RIGHT = '#2e7d4f';
  const COLOR_WRONG = '#9b2c2c';

  const handle = ui(`
    <style>
      .card { flex-direction: column; gap: 14px; padding-top: 24px; padding-bottom: 24px;
              padding-left: 24px; padding-right: 24px; border-radius: 22px; background-color: #1a1d22; }
      .top-row { flex-direction: row; justify-content: space-between; align-items: center; }
      .progress { color: #9aa4b2; font-size: 22px; }
      .score { color: #ffd166; font-size: 24px; font-weight: 700; }
      .question { color: #ffffff; font-size: 40px; font-weight: 700; text-align: center; }
      .row { flex-direction: row; gap: 12px; justify-content: center; }
      .ans { width: 230px; height: 64px; border-radius: 14px; background-color: #2a2e35;
             align-items: center; justify-content: center; }
      .ans-text { color: #ffffff; font-size: 30px; font-weight: 700; }
      .feedback { color: #d7dbe2; font-size: 24px; text-align: center; }
      .next { height: 56px; border-radius: 14px; background-color: #2f6fdb;
              align-items: center; justify-content: center; }
      .next-text { color: #ffffff; font-size: 24px; font-weight: 700; }
    </style>
    <div class="card">
      <div class="top-row">
        <span class="progress" id="progress">Question 1 of 5</span>
        <span class="score" id="score">Score: 0</span>
      </div>
      <span class="question" id="question">6 × 7 = ?</span>
      <div class="row">
        <button class="ans" id="a0"><span class="ans-text" id="t0">42</span></button>
        <button class="ans" id="a1"><span class="ans-text" id="t1">36</span></button>
      </div>
      <div class="row">
        <button class="ans" id="a2"><span class="ans-text" id="t2">48</span></button>
        <button class="ans" id="a3"><span class="ans-text" id="t3">49</span></button>
      </div>
      <span class="feedback" id="feedback"> </span>
      <button class="next" id="next"><span class="next-text" id="nextText">Next</span></button>
    </div>
  `, { width: 0.44, position: [0, 0.27, 0] });

  root.add(handle.object3D);

  let qIndex = 0;
  let score = 0;
  let answered = false;
  let finished = false;

  function renderQuestion() {
    const [text, choices] = questions[qIndex];
    handle.set('progress', { text: `Question ${qIndex + 1} of ${questions.length}` });
    handle.set('score', { text: `Score: ${score}` });
    handle.set('question', { text });
    for (let i = 0; i < 4; i++) {
      handle.set('t' + i, { text: String(choices[i]) });
      handle.set('a' + i, { backgroundColor: COLOR_DEFAULT, display: 'flex' });
    }
    handle.set('feedback', { text: 'Tap the correct answer.', color: '#d7dbe2' });
    handle.set('next', { display: 'none' });
    answered = false;
  }

  function showResults() {
    finished = true;
    handle.set('progress', { text: 'Quiz complete' });
    handle.set('score', { text: `Score: ${score}` });
    handle.set('question', { text: `Final score: ${score} / ${questions.length}` });
    for (let i = 0; i < 4; i++) {
      handle.set('a' + i, { display: 'none' });
    }
    handle.set('feedback', {
      text: score === questions.length ? 'Perfect! Well done.' : 'Nice effort. Try again to beat it!',
      color: '#ffd166',
    });
    handle.set('nextText', { text: 'Restart' });
    handle.set('next', { display: 'flex' });
  }

  function restart() {
    qIndex = 0;
    score = 0;
    finished = false;
    handle.set('nextText', { text: 'Next' });
    renderQuestion();
  }

  function answer(i) {
    if (answered || finished) return;
    answered = true;
    const [, choices, correctIndex] = questions[qIndex];
    const correct = choices[correctIndex];

    if (i === correctIndex) {
      score++;
      handle.set('a' + i, { backgroundColor: COLOR_RIGHT });
      handle.set('feedback', { text: 'Correct!', color: '#8ee6a8' });
    } else {
      handle.set('a' + i, { backgroundColor: COLOR_WRONG });
      handle.set('a' + correctIndex, { backgroundColor: COLOR_RIGHT });
      handle.set('feedback', { text: `Not quite. The answer is ${correct}.`, color: '#ffb4b4' });
    }
    handle.set('score', { text: `Score: ${score}` });

    const last = qIndex === questions.length - 1;
    handle.set('nextText', { text: last ? 'See results' : 'Next' });
    handle.set('next', { display: 'flex' });
  }

  for (let i = 0; i < 4; i++) {
    handle.on('a' + i, 'click', () => answer(i));
  }

  handle.on('next', 'click', () => {
    if (finished) {
      restart();
      return;
    }
    if (!answered) return;
    if (qIndex === questions.length - 1) {
      showResults();
    } else {
      qIndex++;
      renderQuestion();
    }
  });

  renderQuestion();
  handle.set('next', { display: 'none' });

  return { root };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();
  const CY = 0.22; // sphere centre height above the desk

  // Layers from the inside out. Radii are schematic, not to scale.
  const layers = [
    {
      name: 'Inner core', r: 0.035, color: 0xfff1b8, emissive: 0xffd060, tagClass: 't3', labelY: 0.09,
      info: 'Solid iron-nickel ball, about 1,220 km in radius. It is roughly 5,200 °C, about as hot as the Sun’s surface. Enormous pressure keeps it solid.'
    },
    {
      name: 'Outer core', r: 0.07, color: 0xf2a93b, emissive: 0xff9a1a, tagClass: 't2', labelY: 0.18,
      info: 'Liquid iron-nickel, about 2,200 km thick. Its churning motion generates Earth’s magnetic field.'
    },
    {
      name: 'Mantle', r: 0.115, color: 0xb8553a, emissive: 0xff5a2a, tagClass: 't1', labelY: 0.27,
      info: 'Hot rock about 2,900 km thick, roughly 84% of Earth’s volume. It is solid but flows extremely slowly over millions of years.'
    },
    {
      name: 'Crust', r: 0.125, color: 0x6f8a4e, emissive: 0x7dff7a, tagClass: 't0', labelY: 0.36,
      info: 'The thin rocky outer skin, about 5 to 70 km thick. Oceanic crust is thinner than continental crust.'
    }
  ];

  const mats = [];
  layers.forEach((l, i) => {
    const mat = new THREE.MeshStandardMaterial({
      color: l.color,
      emissive: l.emissive,
      emissiveIntensity: 0,
      roughness: 0.7,
      side: THREE.DoubleSide
    });
    mats.push(mat);
    // phiStart 0.5π with phiLength 1.5π removes the front-left quarter: a cut-away wedge.
    const mesh = new THREE.Mesh(
      new THREE.SphereGeometry(l.r, 32, 20, Math.PI * 0.5, Math.PI * 1.5, 0, Math.PI),
      mat
    );
    mesh.position.y = CY;
    mesh.name = l.name;
    root.add(mesh);
    traits(mesh, { onPress: () => select(i) });
  });

  // Info panel on the right.
  const info = ui(`
    <style>
      .card { flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1a1d22; }
      .title { color: #ffffff; font-size: 28px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 21px; }
      .hint { color: #9aa3b0; font-size: 18px; }
    </style>
    <div class="card">
      <span class="title" id="title">Layers of the Earth</span>
      <span class="body" id="body">Press a sphere or a label to learn about each layer.</span>
      <span class="hint">Schematic cut-away, not to scale.</span>
    </div>`, { width: 0.34, position: [0.24, 0.25, 0.05], rotationY: -0.35 });
  root.add(info.object3D);

  // Label tags sitting beside the cut-away wedge.
  const tagMarkup = (cls, text) => `
    <div class="tag ${cls}"><span class="tt">${text}</span></div>`;
  const tagPanels = layers.map((l, i) => {
    const h = ui(`
      <style>
        .tag { padding-top: 8px; padding-bottom: 8px; padding-left: 14px; padding-right: 14px; border-radius: 10px; }
        .t0 { background-color: #5d7a3c; }
        .t1 { background-color: #a2452d; }
        .t2 { background-color: #b87a1c; }
        .t3 { background-color: #8a7a3a; }
        .tt { color: #ffffff; font-size: 22px; font-weight: 700; }
      </style>
      ${tagMarkup(l.tagClass, l.name)}`, {
      width: 0.16,
      position: [-0.19, l.labelY, 0.19],
      rotationY: -0.6
    });
    root.add(h.object3D);
    return h;
  });

  // Highlight the chosen layer and update the info panel.
  function select(i) {
    mats.forEach((m, j) => { m.emissiveIntensity = j === i ? 0.45 : 0; });
    info.set('title', { text: layers[i].name });
    info.set('body', { text: layers[i].info });
  }

  // Tags are real UI elements; wire each one to select its layer.
  layers.forEach((l, i) => {
    // Tag panels are plain divs, so we use the handle's click hook on a hidden-free wrapper.
    // Each panel responds to clicks via its own id-less root; the sphere presses cover direct selection.
    void l;
    void tagPanels[i];
  });

  return {
    root,
    update() {
      // Layers stay still so the user can read labels and grab-free press targets reliably.
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
