      <span class="body" id="detail">Press a layer label to highlight it. Pinch the globe to turn it and look into the cut-away.</span>
      <button class="btn" id="spin"><span class="btn-text" id="spin-text">Start spinning</span></button>
    </div>`, { width: 0.2, position: [-0.29, 0.2, 0.05] });
  root.add(info.object3D);

  let selected = -1;
  let spinOn = false;

  function select(i) {
    selected = i;
    layers.forEach((L, k) => {
      L.mat.emissiveIntensity = L.base;
      L.panel.set('btn', { backgroundColor: k === i ? '#444c58' : '#2a2e35' });
    });
    info.set('layer', { text: layers[i].name, color: layers[i].css });
    info.set('detail', { text: layers[i].detail });
  }
  layers.forEach((L, i) => L.panel.on('btn', 'click', () => select(i)));

  info.on('spin', 'click', () => {
    spinOn = !spinOn;
    info.set('spin-text', { text: spinOn ? 'Stop spinning' : 'Start spinning' });
  });

  const tmp = new THREE.Vector3();
  function updateLines() {
    earth.updateMatrix();
    layers.forEach((L) => {
      tmp.copy(L.anchorV).applyMatrix4(earth.matrix);
      const p = L.line.geometry.attributes.position;
      p.setXYZ(0, tmp.x, tmp.y, tmp.z);
      p.setXYZ(1, labelX - panelHalfW, L.labelY, labelZ);
      p.needsUpdate = true;
    });
  }
  updateLines();

  return {
    root,
    update(time, delta) {
      if (spinOn && !isGrabbed(earth)) earth.rotation.y += delta * 0.2;
      if (selected >= 0) {
        layers[selected].mat.emissiveIntensity = 0.7 + 0.3 * Math.sin(time * 3);
      }
      updateLines();
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Layout ----------
  const R = 0.12;                                  // model radius of Earth (6,371 km)
  const HOME = new THREE.Vector3(-0.2, 0.2, 0);    // centre of the assembled Earth
  const R_INNER = R * 0.19;                        // inner core: 1,220 km radius (true scale)
  const R_OUTER = R * 0.546;                       // outer core: to 3,480 km radius (true scale)
  const R_MANTLE = R * 0.955;                      // crust is drawn thicker than true scale
  const LABEL_X = 0.045, LABEL_Z = 0.03, LABEL_W = 0.17;

  // ---------- Stand ----------
  const standMat = new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.6, metalness: 0.3 });
  const base = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.075, 0.012, 32), standMat);
  base.position.set(HOME.x, 0.006, HOME.z);
  base.name = 'StandBase';
  root.add(base);
  const post = new THREE.Mesh(new THREE.CylinderGeometry(0.004, 0.004, 0.068, 10), standMat);
  post.position.set(HOME.x, 0.046, HOME.z);
  post.name = 'StandPost';
  root.add(post);

  // ---------- Materials ----------
  const crustSurfaceMat = new THREE.MeshStandardMaterial({
    color: 0xffffff, vertexColors: true, roughness: 0.75,
    emissive: 0x2a5fd0, emissiveIntensity: 0,
  });
  const crustRockMat = new THREE.MeshStandardMaterial({
    color: 0x9a6a3c, roughness: 0.85, side: THREE.DoubleSide,
    emissive: 0x9a6a3c, emissiveIntensity: 0,
  });
  const mantleMat = new THREE.MeshStandardMaterial({
    color: 0xd9541e, roughness: 0.7, side: THREE.DoubleSide,
    emissive: 0xc43a10, emissiveIntensity: 0.2,
  });
  const outerCoreMat = new THREE.MeshStandardMaterial({
    color: 0xf59a23, roughness: 0.45, side: THREE.DoubleSide,
    emissive: 0xff8a00, emissiveIntensity: 0.45,
  });
  const innerCoreMat = new THREE.MeshStandardMaterial({
    color: 0xffe27a, roughness: 0.35,
    emissive: 0xffd060, emissiveIntensity: 0.7,
  });
  const dotMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
  const leaderMat = new THREE.MeshBasicMaterial({ color: 0xe8ecf2 });

  // ---------- Geometry helpers ----------
  // Sphere with the quarter wedge between +X and +Z removed (faces the user).
  const PHI_START = Math.PI, PHI_LEN = Math.PI * 1.5;

  function makeShell(name, rOut, rIn, surfaceMat, bodyMat, outerGeo) {
    const g = new THREE.Group();
    g.name = name;
    const outer = new THREE.Mesh(
      outerGeo || new THREE.SphereGeometry(rOut, 36, 18, PHI_START, PHI_LEN), surfaceMat);
    outer.name = name + ' outer surface';
    const inner = new THREE.Mesh(new THREE.SphereGeometry(rIn, 36, 18, PHI_START, PHI_LEN), bodyMat);
    inner.name = name + ' inner surface';
    const ringGeo = new THREE.RingGeometry(rIn, rOut, 32, 1, -Math.PI / 2, Math.PI);
    const faceA = new THREE.Mesh(ringGeo, bodyMat);       // cut face on the +X half-plane
    faceA.name = name + ' cut face A';
    const faceB = new THREE.Mesh(ringGeo, bodyMat);       // cut face on the +Z half-plane
    faceB.rotation.y = -Math.PI / 2;
    faceB.name = name + ' cut face B';
    g.add(outer, inner, faceA, faceB);
    return g;
  }

  // Crust surface with stylised oceans, land and polar ice (vertex colours).
  const crustGeo = new THREE.SphereGeometry(R, 48, 24, PHI_START, PHI_LEN);
  {
    const pos = crustGeo.attributes.position;
    const colors = new Float32Array(pos.count * 3);
    const ocean = new THREE.Color(0x1f5fbf), land = new THREE.Color(0x3f9b4a), ice = new THREE.Color(0xeef3f8);
    const c = new THREE.Color();
    for (let i = 0; i < pos.count; i++) {
      const x = pos.getX(i) / R, y = pos.getY(i) / R, z = pos.getZ(i) / R;
      const n = Math.sin(x * 3.1 + 0.7) * Math.cos(z * 2.7 - 0.4)
        + 0.6 * Math.sin(y * 4.3 + x * 2.2 + 1.9)
        + 0.35 * Math.sin(z * 7.1 + y * 5.3);
      if (Math.abs(y) > 0.9) c.copy(ice);
      else if (n > 0.3) c.copy(land);
      else c.copy(ocean);
      colors[i * 3] = c.r; colors[i * 3 + 1] = c.g; colors[i * 3 + 2] = c.b;
    }
    crustGeo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  }

  const crust = makeShell('Crust', R, R_MANTLE, crustSurfaceMat, crustRockMat, crustGeo);
  const mantle = makeShell('Mantle', R_MANTLE, R_OUTER, mantleMat, mantleMat);
  const outerCore = makeShell('Outer Core', R_OUTER, R_INNER, outerCoreMat, outerCoreMat);
  const innerCore = new THREE.Group();
  innerCore.name = 'Inner Core';
  const innerBall = new THREE.Mesh(new THREE.SphereGeometry(R_INNER, 24, 16), innerCoreMat);
  innerBall.name = 'Inner Core ball';
  innerCore.add(innerBall);

  function faceAnchor(radius, angleDeg) {
    const a = angleDeg * Math.PI / 180;
    return new THREE.Vector3(Math.cos(a) * radius, Math.sin(a) * radius, 0.0015);
  }

  // ---------- Layer data (facts) ----------
  const layers = [
    {
      name: 'Crust', group: crust, color: '#a9713c', short: '0 to 5-70 km deep',
      mats: [crustSurfaceMat, crustRockMat], baseGlow: 0,
      anchor: faceAnchor((R + R_MANTLE) / 2, 40), labelY: 0.29,
      state: 'State: solid rock (basalt, granite)',
      depth: 'Depth: surface to 5-70 km',
      temp: 'Temperature: up to several hundred °C at the base',
      body: "The thin, brittle shell we live on. It is 5-10 km thick under the oceans and 30-70 km under continents: less than 1% of Earth's volume.",
    },
    {
      name: 'Mantle', group: mantle, color: '#d9541e', short: 'down to 2,890 km',
      mats: [mantleMat], baseGlow: 0.2,
      anchor: faceAnchor((R_MANTLE + R_OUTER) / 2, 18), labelY: 0.235,
      state: 'State: solid rock that slowly flows',
      depth: 'Depth: down to 2,890 km',
      temp: 'Temperature: about 1,000 to 3,700 °C',
      body: "The thickest layer: about 2,900 km of hot silicate rock and roughly 84% of Earth's volume. Its slow convection moves the tectonic plates.",
    },
    {
      name: 'Outer core', group: outerCore, color: '#f59a23', short: '2,890 to 5,150 km',
      mats: [outerCoreMat], baseGlow: 0.45,
      anchor: faceAnchor((R_OUTER + R_INNER) / 2, -20), labelY: 0.18,
      state: 'State: liquid iron and nickel',
      depth: 'Depth: 2,890 to 5,150 km',
      temp: 'Temperature: about 4,000 to 5,000 °C',
      body: "A layer of molten metal about 2,260 km thick. Its swirling flow generates Earth's magnetic field.",
    },
    {
      name: 'Inner core', group: innerCore, color: '#ffe27a', short: '5,150 to 6,371 km',
      mats: [innerCoreMat], baseGlow: 0.7,
      anchor: new THREE.Vector3(0.55, -0.45, 0.70).normalize().multiplyScalar(R_INNER + 0.001),
      labelY: 0.125,
      state: 'State: solid iron and nickel',
      depth: 'Depth: 5,150 to 6,371 km (the center)',
      temp: 'Temperature: over 5,000 °C',
      body: "A metal ball about 1,220 km in radius, roughly as hot as the Sun's surface. Enormous pressure keeps it solid.",
    },
  ];

  // ---------- Info panel ----------
  const info = ui(`
    <style>
      .card { flex-direction: column; gap: 10px; padding-top: 20px; padding-bottom: 20px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228;
              width: 480px; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .detail { color: #ffd9a0; font-size: 21px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; margin-top: 4px; }
      .btn { margin-top: 6px; padding-top: 12px; padding-bottom: 12px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #2f6fdb; align-items: center; justify-content: center; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
      .hint { color: #9aa3b0; font-size: 20px; }
    </style>
    <div class="card">
      <span class="title" id="title">Inside the Earth</span>
      <span class="detail" id="state">Radius: 6,371 km</span>
      <span class="detail" id="depth">Four main layers</span>
      <span class="detail" id="temp">Center: over 5,000 °C</span>
      <span class="body" id="body">Press a label or a layer to learn about it. Pinch a layer to pull it out of the cut-away.</span>
      <button class="btn" id="reset"><span class="btn-text">Put layers back</span></button>
      <span class="hint">The crust is drawn thicker than true scale so you can see it.</span>
    </div>`, { width: 0.24, position: [0.28, 0.21, 0.03], rotationY: -0.35 });
  root.add(info.object3D);

  // ---------- Labels, leaders, traits ----------
  function labelMarkup(name, short, color) {
    return `
    <style>
      .lbl { flex-direction: row; align-items: center; gap: 12px; padding-top: 10px; padding-bottom: 10px;
             padding-left: 14px; padding-right: 14px; border-radius: 14px; background-color: #1f2228;
             border-width: 2px; border-color: ${color}; width: 340px; }
      .sw { width: 26px; height: 26px; border-radius: 13px; background-color: ${color}; }
      .col { flex-direction: column; gap: 2px; }
      .name { color: #ffffff; font-size: 24px; font-weight: 700; }
      .depth { color: #b9c0cb; font-size: 20px; }
    </style>
    <button class="lbl" id="btn">
      <div class="sw"></div>
      <div class="col">
        <span class="name">${name}</span>
        <span class="depth">${short}</span>
      </div>
    </button>`;
  }

  const dotGeo = new THREE.SphereGeometry(0.003, 8, 6);
  const leaderGeo = new THREE.CylinderGeometry(0.001, 0.001, 1, 6);
  let selected = -1;

  function select(i) {
    if (selected === i) return;
    selected = i;
    const L = layers[i];
    info.set('title', { text: L.name });
    info.set('state', { text: L.state });
    info.set('depth', { text: L.depth });
    info.set('temp', { text: L.temp });
    info.set('body', { text: L.body });
    for (let k = 0; k < layers.length; k++) {
      layers[k].label.set('btn', { backgroundColor: k === i ? '#3b4352' : '#1f2228' });
    }
  }

  layers.forEach((L, i) => {
    // The layer itself: grabbable and pressable, direct child of root.
    L.group.position.copy(HOME);
    root.add(L.group);
    traits(L.group, { grab: true, onPress: () => select(i) });

    // Anchor dot rides with the layer.
    const dot = new THREE.Mesh(dotGeo, dotMat);
    dot.position.copy(L.anchor);
    dot.name = L.name + ' label anchor';
    L.group.add(dot);

    // Label panel.
    L.label = ui(labelMarkup(L.name, L.short, L.color), {
      width: LABEL_W, position: [LABEL_X, L.labelY, LABEL_Z],
    });
    root.add(L.label.object3D);
    L.label.on('btn', 'click', () => select(i));

    // Leader line from label to layer (follows the layer when it is moved).
    L.labelEnd = new THREE.Vector3(LABEL_X - LABEL_W / 2 - 0.004, L.labelY, LABEL_Z);
    L.leader = new THREE.Mesh(leaderGeo, leaderMat);
    L.leader.name = L.name + ' leader line';
    root.add(L.leader);
    L.wasGrabbed = false;
  });

  info.on('reset', 'click', () => {
    for (let k = 0; k < layers.length; k++) {
      const g = layers[k].group;
      if (isGrabbed(g)) continue;
      g.position.copy(HOME);
      g.quaternion.identity();
    }
  });

  // ---------- Per-frame helpers (no allocation) ----------
  const UP = new THREE.Vector3(0, 1, 0);
  const IDENT = new THREE.Quaternion();
  const vA = new THREE.Vector3();
  const vB = new THREE.Vector3();

  function updateLeader(L) {
    vA.copy(L.anchor).applyQuaternion(L.group.quaternion).add(L.group.position);
    vB.copy(L.labelEnd).sub(vA);
    const len = vB.length();
    if (len < 1e-5) return;
    vB.multiplyScalar(1 / len);
    L.leader.quaternion.setFromUnitVectors(UP, vB);
    L.leader.scale.set(1, len, 1);
    L.leader.position.copy(vA).addScaledVector(vB, len * 0.5);
  }
  for (let k = 0; k < layers.length; k++) updateLeader(layers[k]);

  return {
    root,
    update(time, delta) {
      for (let k = 0; k < layers.length; k++) {
        const L = layers[k];
        const g = L.group;
        const grabbed = isGrabbed(g);
        if (grabbed && !L.wasGrabbed) select(k);
        L.wasGrabbed = grabbed;

        // Gently settle a released layer back into place when it is near home.
        if (!grabbed) {
          const dist = g.position.distanceTo(HOME);
          if (dist < 0.035) {
            if (dist > 0.0004) {
              const step = Math.min(dist, 0.04 * delta);
              vA.copy(HOME).sub(g.position).multiplyScalar(step / dist);
              g.position.add(vA);
            } else {
              g.position.copy(HOME);
            }
            g.quaternion.rotateTowards(IDENT, delta);
          }
        }

        // Selected layer pulses.
        const glow = L.baseGlow + (k === selected ? 0.3 + 0.2 * Math.sin(time * 4) : 0);
        for (let m = 0; m < L.mats.length; m++) L.mats[m].emissiveIntensity = glow;

        updateLeader(L);
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // Basket: open-topped wicker-style cylinder on a flat base, centred at BASKET_CENTER.
  const BASKET_CENTER = new THREE.Vector3(0.22, 0, 0);
  const BASKET_RADIUS = 0.1;
  const BASKET_TOP = 0.14;

  const basketMat = new THREE.MeshStandardMaterial({ color: 0x9a6b3f, roughness: 0.9, side: THREE.DoubleSide });
  const basketWall = new THREE.Mesh(
    new THREE.CylinderGeometry(0.11, 0.09, 0.12, 24, 1, true),
    basketMat,
  );
  basketWall.name = 'BasketWall';
  basketWall.position.set(BASKET_CENTER.x, 0.06, BASKET_CENTER.z);
  root.add(basketWall);

  const basketBase = new THREE.Mesh(
    new THREE.CylinderGeometry(0.09, 0.09, 0.01, 24),
    basketMat,
  );
  basketBase.name = 'BasketBase';
  basketBase.position.set(BASKET_CENTER.x, 0.005, BASKET_CENTER.z);
  root.add(basketBase);

  // Fruit definitions with prices in cents (integers avoid float drift).
  const fruitDefs = [
    {
      name: 'Apple', cents: 50, color: 0xd62828,
      home: new THREE.Vector3(-0.26, 0.03, 0.1),
      make() {
        const m = new THREE.Mesh(
          new THREE.SphereGeometry(0.025, 24, 16),
          new THREE.MeshStandardMaterial({ color: 0xd62828, roughness: 0.4 }),
        );
        const stem = new THREE.Mesh(
          new THREE.CylinderGeometry(0.002, 0.002, 0.012, 6),
          new THREE.MeshStandardMaterial({ color: 0x5a3b1c }),
        );
        stem.position.set(0, 0.03, 0);
        m.add(stem);
        return m;
      },
    },
    {
      name: 'Banana', cents: 25, color: 0xffd23f,
      home: new THREE.Vector3(-0.16, 0.02, 0.0),
      make() {
        const m = new THREE.Mesh(
          new THREE.CapsuleGeometry(0.012, 0.07, 6, 12),
          new THREE.MeshStandardMaterial({ color: 0xffd23f, roughness: 0.6 }),
        );
        m.rotation.z = Math.PI / 2;
        m.scale.set(1, 1, 0.8);
        return m;
      },
    },
    {
      name: 'Orange', cents: 75, color: 0xff8c1a,
      home: new THREE.Vector3(-0.26, 0.03, -0.08),
      make() {
        return new THREE.Mesh(
          new THREE.SphereGeometry(0.03, 24, 16),
          new THREE.MeshStandardMaterial({ color: 0xff8c1a, roughness: 0.7 }),
        );
      },
    },
  ];

  const fruits = fruitDefs.map((def) => {
    const mesh = def.make();
    mesh.name = def.name;
    mesh.position.copy(def.home);
    root.add(mesh);
    traits(mesh, { grab: true });
    return { def, mesh, home: def.home, inBasket: false, wasGrabbed: false };
  });

  let totalCents = 0;

  const isInBasket = (pos) => {
    const dx = pos.x - BASKET_CENTER.x;
    const dz = pos.z - BASKET_CENTER.z;
    const horizontal = Math.sqrt(dx * dx + dz * dz);
    return horizontal < BASKET_RADIUS && pos.y >= 0 && pos.y < BASKET_TOP;
  };

  const money = (cents) => '$' + (cents / 100).toFixed(2);

  const panel = ui(`
    <style>
      .card { flex-direction: column; gap: 12px; padding-top: 20px; padding-bottom: 20px;
              padding-left: 24px; padding-right: 24px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .hint { color: #aeb4bf; font-size: 20px; }
      .row { flex-direction: row; justify-content: space-between; align-items: center; }
      .label { color: #d7dbe2; font-size: 22px; }
      .total { color: #7ee787; font-size: 36px; font-weight: 700; }
      .items { color: #ffffff; font-size: 22px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 18px; padding-right: 18px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Fruit basket</span>
      <span class="hint">Pinch a fruit and drop it in the basket.</span>
      <span class="hint">Apple $0.50 · Banana $0.25 · Orange $0.75</span>
      <div class="row">
        <span class="label">Total</span>
        <span class="total" id="total">$0.00</span>
      </div>
      <span class="items" id="items">Basket is empty</span>
      <button class="btn" id="reset"><span class="btn-text">Reset</span></button>
    </div>`, { width: 0.4, position: [0, 0.3, 0.05], rotationY: 0 });
  root.add(panel.object3D);

  const refreshPanel = () => {
    const names = fruits.filter((f) => f.inBasket).map((f) => f.def.name);
    panel.set('total', { text: money(totalCents) });
    panel.set('items', { text: names.length ? 'In basket: ' + names.join(', ') : 'Basket is empty' });
  };

  panel.on('reset', 'click', () => {
    for (const f of fruits) {
      f.mesh.position.copy(f.home);
      f.inBasket = false;
    }
    totalCents = 0;
    refreshPanel();
  });

  refreshPanel();

  return {
    root,
    update() {
      let changed = false;
      for (const f of fruits) {
        const grabbed = isGrabbed(f.mesh);
        // On release, decide whether the fruit is now inside or outside the basket.
        if (f.wasGrabbed && !grabbed) {
          const inside = isInBasket(f.mesh.position);
          if (inside !== f.inBasket) {
            totalCents += inside ? f.def.cents : -f.def.cents;
            f.inBasket = inside;
            changed = true;
          }
        }
        f.wasGrabbed = grabbed;
      }
      if (changed) refreshPanel();
    },
  };
}
